function tamper_table(p1, p2)
  local v2 = p1[p2]
  table.insert(v1, v2)
  p1[p2] = nil
  local v3

  setrawmetatable(p1, {
    __newindex = function(object, key, value)
      if key == p2 then
        if table.find(v1, value) or value:match("[^%d]%d+") ~= nil and rawlen(value) == 4 then
          v3 = value
        end

        return
      end

      rawset(object, key, value)
    end,
    __index = function(object2, key2)
      if key2 == p2 then
        if v3 then
          local v4 = v3
          v3 = nil
          return v4
        end

        return v2
      end
    end,
  })

  return true
end

function try_bypass()
  for v5, v6 in getgc(true) do
    if type(v6) ~= "table" then
    elseif getrawmetatable(v6) then
    else
      local v7 = nil
      local v8 = nil

      for v9, v10 in v6, nil, nil do
        if type(v10) == "number" and rawequal(v10, 2) then
          v7 = v10
        end

        if rawequal(v10, v6) then
          v8 = v10
        end
      end

      local v11 = v8
      local v12 = rawget(v6, v7)

      if v8 then
        v11 = v7 and v12 and typeof(v12) == "string" and rawlen(v12) == 4
      end

      if v11 then
        if tamper_table(v8, v7) then
          return true
        end
      end
    end
  end

  return false
end

task.spawn(function()
  for i = 1, 10 do
    local v13, v14 = pcall(try_bypass)

