or3=Color3.fromRGB(255,255,255), ZIndex=52})\n\n    local track = create("Frame", {Parent=sf, BackgroundColor3=Color3.fromRGB(19,19,19),\n        Size=UDim2.new(1,-28,0,8), Position=UDim2.new(0,14,0,18),\n        BorderColor3=Color3.fromRGB(30,30,30), ZIndex=50})\n\n    local fl = create("Frame", {Parent=track, BorderSizePixel=0, BackgroundColor3=Color3.fromRGB(91,134,198),\n        Size=UDim2.new((sl.value-sl.min)/(sl.max-sl.min),0,1,0), ZIndex=51})\n\n    local tr = create("TextButton", {Parent=sf, AutoButtonColor=false, BackgroundTransparency=1,\n        Size=UDim2.new(1,0,1,0), Position=UDim2.new(0,0,0,0), Text="", ZIndex=60, Active=true})\n\n    local function getMousePos()\n        local mp = UserInputService:GetMouseLocation()\n        local inset = GuiService:GetGuiInset()\n        return Vector2.new(mp.X + inset.X, mp.Y + inset.Y)\n    end\n\n    local function setFromX(screenX)\n        if not track.Parent then return end\n        local ap = track.AbsolutePosition\n        local as = track.AbsoluteSize\n        if as.X <= 0 then return end\n        local p = math.clamp((screenX - ap.X) / as.X, 0, 1)\n        sl.value = sl.min + (sl.max - sl.min) * p\n        if not sl.precise then sl.value = math.floor(sl.value) end\n        vl.Text = sl.precise and string.format("%.5f", sl.value) or tostring(sl.value)\n        fl.Size = UDim2.new(p, 0, 1, 0)\n        local ok, err = pcall(sl.callback, sl.value)\n        if not ok then warn("[Slider callback]", err) end\n    end\n\n    -- Проверка: мышь над слайдером?\n    local function isOverSlider()\n        if not sf.Parent then return false end\n        local ap = sf.AbsolutePosition\n        local as = sf.AbsoluteSize\n        local mp = getMousePos()\n        return mp.X >= ap.X and mp.X <= ap.X + as.X\n           and mp.Y >= ap.Y and mp.Y <= ap.Y + as.Y\n    end\n\n    -- === ГЛАВНОЕ: ловим клик через глобальный хук ===\n    UserInputService.InputBegan:Connect(function(inp, gpe)\n        if gpe then return end\n        if inp.UserInputType ~= Enum.UserInputType.MouseButton1 then return end\n        if isOverSlider() then\n            sl.drag = true\n            setFromX(getMousePos().X)\n        end\n    end)\n\n    UserInputService.InputChanged:Connect(function(inp)\n        if sl.drag and inp.UserInputType == Enum.UserInputType.MouseMovement then\n            setFromX(getMousePos().X)\n        end\n    end)\n\n    UserInputService.InputEnded:Connect(function(inp)\n        if inp.UserInputType == Enum.UserInputType.MouseButton1 then\n            sl.drag = false\n        end\n    end)\n\n    -- Fallback на прямую кнопку\n    tr.MouseButton1Down:Connect(function()\n        sl.drag = true\n        setFromX(getMousePos().X)\n    end)\n\n    function sl:Set(v)\n        sl.value = math.clamp(v, sl.min, sl.max)\n        local p = (sl.value - sl.min) / (sl.max - sl.min)\n        vl.Text = sl.precise and string.format("%.5f", sl.value) or tostring(sl.value)\n        fl.Size = UDim2.new(p, 0, 1, 0)\n        local ok, err = pcall(sl.callback, sl.value)\n        if not ok then warn("[Slider callback]", err) end\n    end\n\n    reg(tr)\n    return sl\nend\n\t\t\tfunction section:Dropdown(o)\n\t\t\t\to = o or {}\n\t\t\t\tlocal dd = {title=o.title or "Dropdown", options=o.options or {"1","2"},\n\t\t\t\t\tdefault=o.default or o.options[1], callback=o.callback or function() end, open=false}\n\n\t\t\t\tlocal df = create("Frame", {Parent=sc, BackgroundTransparency=1, Size=UDim2.new(1,0,0,35), ZIndex=3, ClipsDescendants=false})\n\t\t\t\tcreate("TextLabel", {Parent=df, TextSize=12, TextXAlignment=Enum.TextXAlignment.Left, BackgroundTransparency=1,\n\t\t\t\t\tSize=UDim2.new(1,0,0,10), Position=UDim2.new(0,13,0,4), Text=dd.title,\n\t\t\t\t\tFontFace=Font.new("rbxasset://fonts/families/Zekton.json"), TextColor3=Color3.fromRGB(255,255,255), ZIndex=3})\n\n\t\t\t\tlocal db = create("TextButton", {Parent=df, AutoButtonColor=false, BackgroundColor3=Color3.fromRGB(19,19,19),\n\t\t\t\t\tSize=UDim2.new(1,-28,0,18), Position=UDim2.new(0,14,0,20), BorderColor3=Color3.fromRGB(30,30,30),\n\t\t\t\t\tText="", ZIndex=100, ClipsDescendants=false})\n\n\t\t\t\tlocal vl = create("TextLabel", {Parent=db, BorderSizePixel=0, TextSize=12, TextXAlignment=Enum.TextXAlignment.Left,\n\t\t\t\t\tBackgroundTransparency=1, Size=UDim2.new(1,-10,1,0), Position=UDim2.new(0,2,0,0), Text=dd.default,\n\t\t\t\t\tFontFace=Font.new("rbxasset://fonts/families/Zekton.json"), TextColor3=Color3.fromRGB(200,200,200), ZIndex=101})\n\n\t\t\t\tlocal sg = df\n\t\t\t\twhile sg and sg.Parent and not sg:IsA("ScreenGui") do sg = sg.Parent end\n\t\t\t\tif not sg or not sg:IsA("ScreenGui") then\n\t\t\t\t\tsg = LocalPlayer:WaitForChild("PlayerGui"):FindFirstChild("Ui")\n\t\t\t\tend\n\n\t\t\t\tlocal outside = create("TextButton", {Parent=sg, Text="", AutoButtonColor=false,\n\t\t\t\t\tBackgroundTransparency=1, Size=UDim2.new(1,0,1,0), Position=UDim2.new(0,0,0,0),\n\t\t\t\t\tVisible=false, ZIndex=900, Active=true})\n\n\t\t\t\tlocal dc = create("Frame", {Parent=sg, Visible=false, BackgroundColor3=Color3.fromRGB(19,19,19),\n\t\t\t\t\tSize=UDim2.new(0,200,0,0), Position=UDim2.new(0,0,0,0), BorderColor3=Color3.fromRGB(30,30,30),\n\t\t\t\t\tZIndex=950, ClipsDescendants=false, Active=true})\n\t\t\t\tcreate("UIListLayout", {Parent=dc, SortOrder=Enum.SortOrder.LayoutOrder})\n\n\t\t\t\tlocal function updatePos()\n\t\t\t\t\tif not db.Parent then return end\n\t\t\t\t\tdc.Position = UDim2.new(0, db.AbsolutePosition.X, 0, db.AbsolutePosition.Y + db.AbsoluteSize.Y)\n\t\t\t\t\tdc.Size = UDim2.new(0, db.AbsoluteSize.X, 0, math.min(#dd.options*15, 150))\n\t\t\t\tend\n\n\t\t\t\tlocal function closeDD()\n\t\t\t\t\tdd.open = false\n\t\t\t\t\tdc.Visible = false\n\t\t\t\t\toutside.Visible = false\n\t\t\t\tend\n\n\t\t\t\toutside.MouseButton1Click:Connect(closeDD)\n\n\t\t\t\tfor _, opt in ipairs(dd.options) do\n\t\t\t\t\tlocal ob = create("TextButton", {Parent=dc, BorderSizePixel=0, AutoButtonColor=false, BackgroundTransparency=1,\n\t\t\t\t\t\tSize=UDim2.new(1,0,0,15), Text=opt, TextSize=12, TextXAlignment=Enum.TextXAlignment.Left,\n\t\t\t\t\t\tFontFace=Font.new("rbxasset://fonts/families/Zekton.json"), ZIndex=951,\n\t\t\t\t\t\tTextColor3 = opt==dd.default and Color3.fromRGB(255,255,255) or Color3.fromRGB(200,200,200)})\n\t\t\t\t\tcreate("UIPadding", {Parent=ob, PaddingLeft=UDim.new(0,4)})\n\t\t\t\t\tob.MouseButton1Click:Connect(function()\n\t\t\t\t\t\tvl.Text = opt\n\t\t\t\t\t\tdd.callback(opt)\n\t\t\t\t\t\tcloseDD()\n\t\t\t\t\t\tfor _, ch in ipairs(dc:GetChildren()) do\n\t\t\t\t\t\t\tif ch:IsA("TextButton") then\n\t\t\t\t\t\t\t\tch.TextColor3 = ch.Text==opt and Color3.fromRGB(255,255,255) or Color3.fromRGB(200,200,200)\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend)\n\t\t\t\tend\n\n\t\t\t\tdb.MouseButton1Click:Connect(function()\n\t\t\t\t\tdd.open = not dd.open\n\t\t\t\t\tif dd.open then\n\t\t\t\t\t\tupdatePos()\n\t\t\t\t\t\tdc.Visible = true\n\t\t\t\t\t\toutside.Visible = true\n\t\t\t\t\telse\n\t\t\t\t\t\tcloseDD()\n\t\t\t\t\tend\n\t\t\t\tend)\n\n\t\t\t\ttask.spawn(function()\n\t\t\t\t\twhile db and db.Parent do\n\t\t\t\t\t\tif dd.open then updatePos() end\n\t\t\t\t\t\ttask.wait(0.05)\n\t\t\t\t\tend\n\t\t\t\t\tif dc and dc.Parent then dc:Destroy() end\n\t\t\t\t\tif outside and outside.Parent then outside:Destroy() end\n\t\t\t\tend)\n\n\t\t\t\treg(db)\n\t\t\t\treturn dd\n\t\t\tend\n\n\t\t\tfunction section:Input(o)\n\t\t\t\to = o or {}\n\t\t\t\tlocal inp = {title=o.title or "Input", value=o.default or "", callback=o.callback or function() end}\n\t\t\t\tlocal f = create("Frame", {Parent=sc, BackgroundTransparency=1, Size=UDim2.new(1,0,0,35)})\n\t\t\t\tcreate("TextLabel", {Parent=f, TextSize=12, TextXAlignment=Enum.TextXAlignment.Left,\n\t\t\t\t\tBackgroundTransparency=1, Size=UDim2.new(1,0,0,10), Position=UDim2.new(0,13,0,2),\n\t\t\t\t\tText=inp.title, FontFace=Font.new("rbxasset://fonts/families/Zekton.json"),\n\t\t\t\t\tTextColor3=Color3.fromRGB(255,255,255)})\n\t\t\t\tlocal tb = create("TextBox", {Parent=f, BackgroundColor3=Color3.fromRGB(19,19,19),\n\t\t\t\t\tSize=UDim2.new(1,-28,0,18), Position=UDim2.new(0,14,0,15),\n\t\t\t\t\tBorderColor3=Color3.fromRGB(30,30,30), Text=inp.value, TextSize=12,\n\t\t\t\t\tTextColor3=Color3.fromRGB(230,230,230), Font=Enum.Font.Code,\n\t\t\t\t\tTextXAlignment=Enum.TextXAlignment.Left, ClearTextOnFocus=false})\n\t\t\t\tcreate("UIPadding", {Parent=tb, PaddingLeft=UDim.new(0,4)})\n\t\t\t\ttb.FocusLost:Connect(function()\n\t\t\t\t\tinp.value = tb.Text\n\t\t\t\t\tinp.callback(tb.Text)\n\t\t\t\tend)\n\t\t\t\tfunction inp:Set(v) inp.value=v; tb.Text=v end\n\t\t\t\tfunction inp:Get() return inp.value end\n\t\t\t\treg(tb)\n\t\t\t\treturn inp\n\t\t\tend\n\n\t\t\tfunction section:Button(o)\n\t\t\t\to = o or {}\n\t\t\t\tlocal btn = create("TextButton", {Parent=sc, BackgroundColor3=Color3.fromRGB(19,19,19),\n\t\t\t\t\tSize=UDim2.new(1,-28,0,18), Position=UDim2.new(0,14,0,0), BorderColor3=Color3.fromRGB(30,30,30),\n\t\t\t\t\tText=o.title or "Button", TextSize=12, TextColor3=Color3.fromRGB(230,230,230),\n\t\t\t\t\tFont=Enum.Font.Code, AutoButtonColor=true})\n\t\t\t\tbtn.MouseButton1Click:Connect(function()\n\t\t\t\t\tif o.callback then o.callback() end\n\t\t\t\tend)\n\t\t\t\treg(btn)\n\t\t\t\treturn btn\n\t\t\tend\n\n\t\t\ttab.sections[#tab.sections+1] = section\n\t\t\treturn section\n\t\tend\n\t\treturn tab\n\tend\n\treturn window\nend\n\n-- ===== CONFIG SYSTEM =====\nlocal CONFIG_FOLDER = "monoton_configs"\nif not isfolder(CONFIG_FOLDER) then makefolder(CONFIG_FOLDER) end\n\nlocal ConfigSystem = {registry = {}, counter = 0}\n\nfunction ConfigSystem:Register(elemType, obj, customId)\n\tself.counter = self.counter + 1\n\tlocal id = customId or (elemType .. "_" .. self.counter)\n\tself.registry[id] = {type = elemType, obj = obj}\n\treturn id\nend\n\nfunction ConfigSystem:Serialize()\n\tlocal data = {_version = 1, _time = os.time()}\n\tfor id, entry in pairs(self.registry) do\n\t\tlocal obj = entry.obj\n\t\tlocal t = entry.type\n\t\tif t == "toggle" then data[id] = {t="toggle", v=obj.state}\n\t\telseif t == "slider" then data[id] = {t="slider", v=obj.value}\n\t\telseif t == "dropdown" then data[id] = {t="dropdown", v=obj.default}\n\t\telseif t == "colorpicker" then\n\t\t\tlocal c = obj.color\n\t\t\tdata[id] = {t="color", v={c.R, c.G, c.B}}\n\t\tend\n\tend\n\treturn data\nend\n\nfunction ConfigSystem:Deserialize(data)\n\tif type(data) ~= "table" then return 0, 0 end\n\tlocal loaded, failed = 0, 0\n\tfor id, entry in pairs(data) do\n\t\tif type(entry) == "table" and entry.t then\n\t\t\tlocal reg = self.registry[id]\n\t\t\tif reg then\n\t\t\t\tlocal obj = reg.obj\n\t\t\t\tlocal ok = pcall(function()\n\t\t\t\t\tif entry.t == "toggle" then\n\t\t\t\t\t\tif obj.Set then obj:Set(entry.v) else obj.state = entry.v; if obj.callback then obj.callback(entry.v) end end\n\t\t\t\t\telseif entry.t == "slider" then\n\t\t\t\t\t\tif obj.Set then obj:Set(entry.v) else obj.value = entry.v; if obj.callback then obj.callback(entry.v) end end\n\t\t\t\t\telseif entry.t == "dropdown" then\n\t\t\t\t\t\tif type(entry.v) == "string" and obj.callback then obj.callback(entry.v) end\n\t\t\t\t\telseif entry.t == "color" and type(entry.v) == "table" and #entry.v >= 3 then\n\t\t\t\t\t\tlocal c = Color3.new(entry.v[1], entry.v[2], entry.v[3])\n\t\t\t\t\t\tobj.color = c\n\t\t\t\t\t\tif obj.callback then obj.callback(c) end\n\t\t\t\t\tend\n\t\t\t\tend)\n\t\t\t\tif ok then loaded = loaded + 1 else failed = failed + 1 end\n\t\t\tend\n\t\tend\n\tend\n\treturn loaded, failed\nend\n\nfunction ConfigSystem:Save(name)\n\tif not name or name == "" then return false, "Empty" end\n\tlocal path = CONFIG_FOLDER .. "/" .. name .. ".json"\n\tlocal ok, err = pcall(function() writefile(path, HttpService:JSONEncode(self:Serialize())) end)\n\treturn ok, err\nend\n\nfunction ConfigSystem:Load(name)\n\tif not name or name == "" then return false, "Empty" end\n\tlocal path = CONFIG_FOLDER .. "/" .. name .. ".json"\n\tif not isfile(path) then return false, "Not found" end\n\tlocal ok, data = pcall(function() return HttpService:JSONDecode(readfile(path)) end)\n\tif not ok then return false, "Bad JSON" end\n\tlocal loaded, failed = self:Deserialize(data)\n\treturn true, ("%d / %d"):format(loaded, failed or 0)\nend\n\nfunction ConfigSystem:Delete(name)\n\tlocal path = CONFIG_FOLDER .. "/" .. name .. ".json"\n\tif isfile(path) then delfile(path) return true end\n\treturn false\nend\n\nfunction ConfigSystem:List()\n\tlocal out = {}\n\tif not listfiles then return out end\n\tlocal ok, files = pcall(listfiles, CONFIG_FOLDER)\n\tif not ok or not files then return out end\n\tfor _, f in ipairs(files) do\n\t\tlocal n = f:match("([^/\\\\]+)%.json$")\n\t\tif n then table.insert(out, n) end\n\tend\n\ttable.sort(out)\n\treturn out\nend\n\n_G.ConfigSystem = ConfigSystem\n\n-- ===== THEME =====\nlocal UITheme = {\n\tBG=Color3.fromRGB(21,21,21), Panel=Color3.fromRGB(14,14,14),\n\tSection=Color3.fromRGB(21,21,21), Element=Color3.fromRGB(18,18,18),\n\tElementDark=Color3.fromRGB(30,30,30), Accent=Color3.fromRGB(91,134,198),\n\tText=Color3.fromRGB(255,255,255), TextDim=Color3.fromRGB(200,200,200),\n\tStroke=Color3.fromRGB(29,29,29),\n\tCornerRadius=UDim.new(0,4), Plastic=true, Transparency=0.0,\n\tBlur=false, Glow=false, registeredGuis={},\n}\nfunction UITheme:Register(gui) table.insert(self.registeredGuis, gui) return gui end\nfunction UITheme:ApplyTo(obj)\n\tif not obj or not obj.Parent then return end\n\tlocal class = obj.ClassName\n\tif class=="Frame" or class=="TextButton" or class=="TextBox" or class=="ImageButton" then\n\t\tif obj.BackgroundTransparency < 0.99 then\n\t\t\tif obj.Name=="Main" then obj.BackgroundColor3 = self.BG; obj.BackgroundTransparency = self.Transparency\n\t\t\telseif obj.Name=="Section" then obj.BackgroundColor3 = self.Section; obj.BackgroundTransparency = self.Transparency\n\t\t\telse\n\t\t\t\tlocal bg = obj.BackgroundColor3\n\t\t\t\tlocal lum = bg.R*0.299 + bg.G*0.587 + bg.B*0.114\n\t\t\t\tif lum < 0.06 then obj.BackgroundColor3 = self.Panel\n\t\t\t\telseif lum < 0.12 then obj.BackgroundColor3 = self.Element end\n\t\t\tend\n\t\tend\n\tend\n\tif class=="TextLabel" or class=="TextButton" or class=="TextBox" then\n\t\tlocal tc = obj.TextColor3\n\t\tlocal tl = tc.R*0.299 + tc.G*0.587 + tc.B*0.114\n\t\tif tl > 0.8 then obj.TextColor3 = self.Text\n\t\telseif tl > 0.5 then obj.TextColor3 = self.TextDim end\n\tend\n\tlocal stroke = obj:FindFirstChildOfClass("UIStroke")\n\tif stroke and self.Plastic then stroke.Color = self.Stroke; stroke.Transparency = 0.3; stroke.Thickness = 1 end\n\tif self.Plastic and (class=="Frame" or class=="TextButton" or class=="TextBox" or class=="ImageButton") then\n\t\tlocal corner = obj:FindFirstChildOfClass("UICorner")\n\t\tif not corner and obj.Name ~= "Main" then\n\t\t\tlocal sz = obj.AbsoluteSize\n\t\t\tif sz.Y > 0 and sz.Y <= 40 then\n\t\t\t\tcorner = Instance.new("UICorner"); corner.CornerRadius = self.CornerRadius; corner.Parent = obj\n\t\t\tend\n\t\telseif corner then corner.CornerRadius = self.CornerRadius end\n\tend\n\tfor _, child in ipairs(obj:GetChildren()) do self:ApplyTo(child) end\nend\nfunction UITheme:Apply()\n\tfor _, gui in ipairs(self.registeredGuis) do if gui and gui.Parent then self:ApplyTo(gui) end end\nend\nfunction UITheme:SetColor(key, color) self[key] = color; self:Apply() end\n_G.UITheme = UITheme\n\n-- ===== FPS BOOST =====\nlocal FPSBoost = {Enabled=false, RemoveFog=true, RemoveShadows=true, RemovePostFX=true,\n\tRemoveParticles=true, RemoveTextures=false, LowerQuality=true, HideSky=false, NoTerrain=false,\n\tsavedState={}, connection=nil, _partCache=nil, _textureCache=nil}\nfunction FPSBoost:Save()\n\tself.savedState = {FogEnd=Lighting.FogEnd, FogStart=Lighting.FogStart, Brightness=Lighting.Brightness,\n\t\tGlobalShadows=Lighting.GlobalShadows, Ambient=Lighting.Ambient, OutdoorAmbient=Lighting.OutdoorAmbient, Children={}}\n\tfor _, child in ipairs(Lighting:GetChildren()) do\n\t\tself.savedState.Children[child] = {Enabled = child:IsA("PostEffect") and child.Enabled or nil}\n\tend\nend\nfunction FPSBoost:Apply()\n\tif not self.Enabled then return end\n\tif self.RemoveFog then Lighting.FogEnd = 9e9; Lighting.FogStart = 9e9 end\n\tif self.RemoveShadows then Lighting.GlobalShadows = false; Lighting.Brightness = 2\n\t\tLighting.Ambient = Color3.fromRGB(180,180,180); Lighting.OutdoorAmbient = Color3.fromRGB(180,180,180) end\n\tif self.RemovePostFX then\n\t\tfor _, c in ipairs(Lighting:GetChildren()) do\n\t\t\tif (c:IsA("BlurEffect") and c.Name ~= "MonotonMenuBlur") or c:IsA("BloomEffect") or c:IsA("SunRaysEffect")\n\t\t\tor c:IsA("ColorCorrectionEffect") or c:IsA("DepthOfFieldEffect") then\n\t\t\t\tif not c:GetAttribute("FPSKeep") then c.Enabled = false end\n\t\t\tend\n\t\tend\n\tend\n\tif self.HideSky then for _, c in ipairs(Lighting:GetChildren()) do if c:IsA("Sky") then c.Parent = nil end end end\n\tif self.RemoveParticles then\n\t\tif not self._partCache or #self._partCache == 0 then\n\t\t\tself._partCache = {}\n\t\t\tfor _, d in ipairs(Workspace:GetDescendants()) do\n\t\t\t\tif d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Smoke") or d:IsA("Fire") or d:IsA("Sparkles") then\n\t\t\t\t\ttable.insert(self._partCache, d)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tfor i = 1, #self._partCache do local d = self._partCache[i]; if d and d.Parent then d.Enabled = false end end\n\tend\n\tif self.RemoveTextures then\n\t\tif not self._textureCache or #self._textureCache == 0 then\n\t\t\tself._textureCache = {}\n\t\t\tfor _, d in ipairs(Workspace:GetDescendants()) do\n\t\t\t\tif d:IsA("Decal") or d:IsA("Texture") then table.insert(self._textureCache, d) end\n\t\t\tend\n\t\tend\n\t\tfor i = 1, #self._textureCache do local d = self._textureCache[i]; if d and d.Parent then d.Transparency = 1 end end\n\tend\n\tif self.LowerQuality and settings then pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end) end\n\tif self.NoTerrain then\n\t\tpcall(function()\n\t\t\tWorkspace.Terrain.WaterWaveSize = 0; Workspace.Terrain.WaterWaveSpeed = 0\n\t\t\tWorkspace.Terrain.WaterReflectance = 0; Workspace.Terrain.WaterTransparency = 1\n\t\tend)\n\tend\nend\nfunction FPSBoost:Restore()\n\tlocal s = self.savedState\n\tif not s or not s.Brightness then return end\n\tLighting.FogEnd = s.FogEnd; Lighting.FogStart = s.FogStart\n\tLighting.Brightness = s.Brightness; Lighting.GlobalShadows = s.GlobalShadows\n\tLighting.Ambient = s.Ambient; Lighting.OutdoorAmbient = s.OutdoorAmbient\n\tfor child, state in pairs(s.Children or {}) do\n\t\tif child and child.Parent and state.Enabled ~= nil then child.Enabled = state.Enabled end\n\tend\nend\nfunction FPSBoost:Toggle(on)\n\tself.Enabled = on\n\tif on then\n\t\tself._partCache = nil; self._textureCache = nil\n\t\tself:Save(); self:Apply()\n\t\tif not self.connection then\n\t\t\tself.connection = task.spawn(function()\n\t\t\t\twhile self.Enabled do self:Apply(); task.wait(3) end\n\t\t\t\tself.connection = nil\n\t\t\tend)\n\t\tend\n\telse\n\t\tif self.connection and type(self.connection) == "RBXScriptConnection" then self.connection:Disconnect() end\n\t\tself.connection = nil; self:Restore()\n\tend\nend\n_G.FPSBoost = FPSBoost\n\n-- ===== AUTO-REGISTER =====\ndo\n\tlocal origWindow = ui.Window\n\tui.Window = function(self, opts)\n\t\tlocal win = origWindow(self, opts)\n\t\tlocal origTab = win.Tab\n\t\twin.Tab = function(self2, name)\n\t\t\tlocal tab = origTab(self2, name)\n\t\t\tlocal origSec = tab.Section\n\t\t\ttab.Section = function(self3, secName, side)\n\t\t\t\tlocal sec = origSec(self3, secName, side)\n\t\t\t\tfunction wrap(origFn, kind)\n\t\t\t\t\treturn function(self4, o)\n\t\t\t\t\t\tlocal el = origFn(self4, o)\n\t\t\t\t\t\tif _G.ConfigSystem then\n\t\t\t\t\t\t\tpcall(function()\n\t\t\t\t\t\t\t\t_G.ConfigSystem:Register(kind, el, (name or "tab").."/"..(secName or "sec").."/"..((o and o.title) or kind))\n\t\t\t\t\t\t\tend)\n\t\t\t\t\t\tend\n\t\t\t\t\t\treturn el\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tsec.Toggle = wrap(sec.Toggle, "toggle")\n\t\t\t\tsec.Slider = wrap(sec.Slider, "slider")\n\t\t\t\tsec.Dropdown = wrap(sec.Dropdown, "dropdown")\n\t\t\t\treturn sec\n\t\t\tend\n\t\t\treturn tab\n\t\tend\n\t\treturn win\n\tend\nend\n\n-- ===== KEY SYSTEM =====\nlocal TOKEN = "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"\nlocal KEYS_URL = "https://raw.githubusercontent.com/monoton-cc/monoton/refs/heads/main/keys1.txt"\n\nfunction getKeys()\n\tlocal ok, res = pcall(function()\n\t\tif syn and syn.request then\n\t\t\tlocal r = syn.request({Url=KEYS_URL, Method="GET", Headers={["Authorization"]="token "..TOKEN}})\n\t\t\tif r.StatusCode==200 then return r.Body else error(r.StatusCode) end\n\t\tend\n\t\tif http and http.request then\n\t\t\tlocal r = http.request({Url=KEYS_URL, Method="GET", Headers={["Authorization"]="token "..TOKEN}})\n\t\t\tif r.StatusCode==200 then return r.Body else error(r.StatusCode) end\n\t\tend\n\t\treturn game:HttpGet(KEYS_URL, true, {["Authorization"]="token "..TOKEN})\n\tend)\n\tif ok then return res else error("Failed: "..tostring(res)) end\nend\n\nfunction createKeyGUI()\n\tlocal TweenService = game:GetService("TweenService")\n\tlocal CoreGui = game:GetService("CoreGui")\n\tlocal PlayerGui = LocalPlayer:WaitForChild("PlayerGui")\n\tlocal UserInputService = game:GetService("UserInputService")\n\tlocal DISCORD_INVITE = "https://discord.gg/fnVhrGRW9m"\n\n\tlocal sg = Instance.new("ScreenGui")\n\tsg.Name = "monoton_key"; sg.IgnoreGuiInset = true; sg.ResetOnSpawn = false; sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n\tpcall(function() sg.Parent = CoreGui end)\n\tif not sg.Parent then sg.Parent = PlayerGui end\n\n\tlocal dim = Instance.new("Frame")\n\tdim.Size = UDim2.new(1, 0, 1, 0); dim.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n\tdim.BackgroundTransparency = 1; dim.BorderSizePixel = 0; dim.ZIndex = 1; dim.Parent = sg\n\tTweenService:Create(dim, TweenInfo.new(0.4), {BackgroundTransparency = 0.5}):Play()\n\n\tlocal fr = Instance.new("Frame")\n\tfr.Size = U