tWrapped = true; status.ZIndex = 3; status.Parent = fr\n\n\tlocal footer = Instance.new("TextLabel")\n\tfooter.Size = UDim2.new(1, -40, 0, 20); footer.Position = UDim2.new(0, 20, 1, -26); footer.BackgroundTransparency = 1\n\tfooter.Text = "monoton.cc"; footer.TextColor3 = Color3.fromRGB(70, 70, 85)\n\tfooter.Font = Enum.Font.Gotham; footer.TextSize = 11; footer.TextXAlignment = Enum.TextXAlignment.Left\n\tfooter.ZIndex = 3; footer.Parent = fr\n\n\tgetKey.MouseButton1Click:Connect(function()\n\t\tlocal copied = false\n\t\tpcall(function() setclipboard(DISCORD_INVITE); copied = true end)\n\t\tif not copied and toclipboard then pcall(function() toclipboard(DISCORD_INVITE); copied = true end) end\n\t\tlocal old = getKey.Text\n\t\tgetKey.Text = "Copied!"; getKey.TextColor3 = Color3.fromRGB(120, 220, 140)\n\t\tstatus.Text = "Discord: " .. DISCORD_INVITE; status.TextColor3 = Color3.fromRGB(120, 180, 240)\n\t\tlocal orig = getKey.BackgroundColor3\n\t\tTweenService:Create(getKey, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(60, 120, 80)}):Play()\n\t\ttask.wait(2)\n\t\tif getKey.Parent then\n\t\t\tgetKey.Text = old; getKey.TextColor3 = Color3.fromRGB(220, 220, 230)\n\t\t\tTweenService:Create(getKey, TweenInfo.new(0.3), {BackgroundColor3 = orig}):Play()\n\t\tend\n\tend)\n\n\tfr.Size = UDim2.new(0, 0, 0, 0); fr.Position = UDim2.new(0.5, 0, 0.5, 0)\n\tTweenService:Create(fr, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out),\n\t\t{Size = UDim2.new(0, 420, 0, 280), Position = UDim2.new(0.5, -210, 0.5, -140)}):Play()\n\n\treturn sg, tb, verify, status\nend\n\nfunction verifyKey(key)\n\tif not key or key=="" then return false end\n\tlocal ok, content = pcall(getKeys)\n\tif not ok then return false, "Failed to load key database." end\n\tfor line in string.gmatch(content, "[^\\r\\n]+") do\n\t\tlocal k = line:match("^%s*(.-)%s*$")\n\t\tif k==key then return true end\n\tend\n\treturn false, "Key not found."\nend\n\n-- ============================================================\n-- ===== MAIN SCRIPT =====\n-- ============================================================\nfunction loadMainScript()\n\tif _G.MonotonLoaded then return end\n\t_G.MonotonLoaded = true\n\nlocal PenCheckSettings = {\n\tEnabled = false,\n\tMaxPen = 4,\n\tRayLength = 1000,\n}\n\ntask.spawn(function()\n\tlocal PenText = Drawing.new("Text")\n\tPenText.Visible   = false\n\tPenText.Center    = true\n\tPenText.Outline   = true\n\tPenText.Font      = 2       -- Zekton / Arial Bold\n\tPenText.Size      = 18\n\tPenText.Color     = Color3.fromRGB(0, 255, 0)\n\tPenText.ZIndex    = 1002\n\n\tlocal penParams = RaycastParams.new()\n\tpenParams.FilterType = Enum.RaycastFilterType.Exclude\n\tpenParams.CollisionGroup = "Bullet"     -- как в оригинале Wurfef\n\tpenParams.IgnoreWater = true\n\n\tRunService.RenderStepped:Connect(function()\n\t\tpcall(function()\n\t\t\tlocal cam = Workspace.CurrentCamera\n\t\t\tif not cam then PenText.Visible = false; return end\n\n\t\t\tif not PenCheckSettings.Enabled then\n\t\t\t\tPenText.Visible = false\n\t\t\t\treturn\n\t\t\tend\n\n\t\t\tPenText.Position = Vector2.new(\n\t\t\t\tcam.ViewportSize.X / 2,\n\t\t\t\tcam.ViewportSize.Y / 2 - 70\n\t\t\t)\n\n\t\t\tlocal ignore = {LocalPlayer.Character, cam, CubeCheckerPart}\n\t\t\tpenParams.FilterDescendantsInstances = ignore\n\n\t\t\tlocal res = Workspace:Raycast(\n\t\t\t\tcam.CFrame.Position,\n\t\t\t\tcam.CFrame.LookVector * PenCheckSettings.RayLength,\n\t\t\t\tpenParams\n\t\t\t)\n\n\t\t\tif not res then\n\t\t\t\tPenText.Visible = false\n\t\t\t\treturn\n\t\t\tend\n\n\t\t\tlocal stats = GetPenetrationStats(\n\t\t\t\tcam.CFrame.Position,\n\t\t\t\tcam.CFrame.LookVector,\n\t\t\t\tPenCheckSettings.MaxPen,\n\t\t\t\t{LocalPlayer.Character, cam, CubeCheckerPart},\n\t\t\t\tnil\n\t\t\t)\n\n\t\t\tif stats and stats.Success then\n\t\t\t\tPenText.Visible = true\n\t\t\t\tPenText.Text = string.format("WALLBANG: YES\\n(%.1f studs)", stats.TotalThickness or 0)\n\t\t\t\tPenText.Color = Color3.fromRGB(0, 255, 0)\n\t\t\telse\n\t\t\t\tPenText.Visible = true\n\t\t\t\tlocal reason = stats and stats.FailReason or "Unknown"\n\t\t\t\tPenText.Text = string.format("WALLBANG: NO\\n(%s)", reason)\n\t\t\t\tPenText.Color = Color3.fromRGB(255, 0, 0)\n\t\t\tend\n\t\tend)\n\tend)\nend)\n\n-- ============================================================\n--  PENETRATION CHECK TEXT (WALLBANG OVERLAY)\n-- ============================================================\nlocal PenCheckSettings = {\n\tEnabled = false,\n\tMaxPen = 4,        -- насколько глубоко разрешено "прошивать" (studs)\n\tRayLength = 1000,  -- длина луча проверки\n}\n\n-- =========================================================================\n-- [ CUBE CHECKER - RAINBOW MODE (Wurfef flat square) ]\n-- =========================================================================\n\nlocal CubeCheckerSettings = {\n    Enabled = false,             -- стартует выключенным, включается через UI\n    Color = Color3.fromRGB(255, 0, 0),\n    Rainbow = false,\n    Size = 1.5,\n    MaxDist = 20,\n}\n\nlocal BulletImpactV1Part = Instance.new("Part")\nBulletImpactV1Part.Name = "CubeChecker_Physical"\nBulletImpactV1Part.Size = Vector3.new(1.5, 1.5, 0.01)\nBulletImpactV1Part.Anchored = true\nBulletImpactV1Part.CanCollide = false\nBulletImpactV1Part.CanQuery = false\nBulletImpactV1Part.CanTouch = false\nBulletImpactV1Part.Material = Enum.Material.Neon\nBulletImpactV1Part.Transparency = 0.98\nBulletImpactV1Part.Parent = nil\n\nlocal selectionBox = Instance.new("SelectionBox")\nselectionBox.Adornee = BulletImpactV1Part\nselectionBox.Color3 = Color3.fromRGB(255, 0, 0)\nselectionBox.LineThickness = 0.04\nselectionBox.Transparency = 0.2\nselectionBox.Parent = BulletImpactV1Part\n\nlocal impactRayParams = RaycastParams.new()\nimpactRayParams.FilterType = Enum.RaycastFilterType.Exclude\nimpactRayParams.IgnoreWater = true\n\nRunService.RenderStepped:Connect(function()\n    pcall(function()\n        local cam = Workspace.CurrentCamera\n        if not cam then return end\n\n        local enabled = CubeCheckerSettings.Enabled\n        BulletImpactV1Part.Parent = enabled and Workspace or nil\n\n        if not enabled then return end\n\n        local sizeVal = CubeCheckerSettings.Size or 1.5\n        local maxDist = CubeCheckerSettings.MaxDist or 20\n        BulletImpactV1Part.Size = Vector3.new(sizeVal, sizeVal, 0.01)\n\n        local userColor = CubeCheckerSettings.Color or Color3.fromRGB(255, 0, 0)\n\n        if CubeCheckerSettings.Rainbow then\n            local hue = (tick() % 5) / 5\n            userColor = Color3.fromHSV(hue, 1, 1)\n        end\n\n        local origin = cam.CFrame.Position\n        local direction = cam.CFrame.LookVector * maxDist\n        impactRayParams.FilterDescendantsInstances = {LocalPlayer.Character, BulletImpactV1Part}\n        local result = Workspace:Raycast(origin, direction, impactRayParams)\n\n        if result then\n            BulletImpactV1Part.Parent = Workspace\n            BulletImpactV1Part.CFrame = CFrame.lookAt(result.Position + (result.Normal * 0.02), result.Position + result.Normal)\n            BulletImpactV1Part.Color = userColor\n            selectionBox.Color3 = userColor\n        else\n            BulletImpactV1Part.Parent = nil\n        end\n    end)\nend)\n\nprint("[CUBE] Loaded (Wurfef flat square style)")\n    -- ============================================================\n--  CUSTOM HAND POSITION\n-- ============================================================\nlocal CustomHandsSettings = {Enabled=false, X=0.2, Y=-0.155, Z=0.075}\n\nRunService.RenderStepped:Connect(function()\n\tpcall(function()\n\t\tif not CustomHandsSettings.Enabled then return end\n\t\tfor _, child in ipairs(Camera:GetChildren()) do\n\t\t\tif child:IsA("Model") then\n\t\t\t\tlocal statsFolder = child:FindFirstChild("Stats")\n\t\t\t\tif statsFolder then\n\t\t\t\t\tlocal defaultVal = statsFolder:FindFirstChild("Default")\n\t\t\t\t\tif defaultVal and defaultVal:IsA("Vector3Value") then\n\t\t\t\t\t\tdefaultVal.Value = Vector3.new(\n\t\t\t\t\t\t\tCustomHandsSettings.X,\n\t\t\t\t\t\t\tCustomHandsSettings.Y,\n\t\t\t\t\t\t\tCustomHandsSettings.Z\n\t\t\t\t\t\t)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\nend)\n\n\tFakeDuckSettings = {Enabled=false, Key=Enum.KeyCode.LeftControl, HeightOffset=-1.5, Mode="Lower"}\n\tlocal fdOriginalHipHeight = 2\n\tlocal fdCurrentShift = 0\n\nlocal lastHipHeight = nil\nfunction FakeDuckTick()\n    if not FakeDuckSettings.Enabled then\n        if lastHipHeight then\n            local char = LocalPlayer.Character\n            local hum = char and char:FindFirstChildOfClass("Humanoid")\n            if hum then hum.HipHeight = fdOriginalHipHeight end\n            lastHipHeight = nil\n        end\n        return\n    end\n    local char = LocalPlayer.Character\n    if not char then return end\n    local hum = char:FindFirstChildOfClass("Humanoid")\n    if not hum then return end\n\n    local targetShift\n    if UserInputService:IsKeyDown(FakeDuckSettings.Key) then\n        targetShift = (FakeDuckSettings.Mode == "Lower") and FakeDuckSettings.HeightOffset or math.abs(FakeDuckSettings.HeightOffset)\n    else\n        targetShift = 0\n    end\n    fdCurrentShift = fdCurrentShift + (targetShift - fdCurrentShift) * 0.3\n\n    local newHip = fdOriginalHipHeight + fdCurrentShift\n    if lastHipHeight ~= newHip then\n        hum.HipHeight = newHip\n        lastHipHeight = newHip\n    end\nend\n\n\tLocalPlayer.CharacterAdded:Connect(function(char)\n\t\ttask.wait(0.3)\n\t\tlocal hum = char:FindFirstChildOfClass("Humanoid")\n\t\tif hum then fdOriginalHipHeight = hum.HipHeight end\n\tend)\n\tif LocalPlayer.Character then\n\t\tlocal hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")\n\t\tif hum then fdOriginalHipHeight = hum.HipHeight end\n\tend\n\n\tPeekAssistSettings = {Enabled=false, KeyLeft=Enum.KeyCode.Q, KeyRight=Enum.KeyCode.E, Offset=3.5, Smoothness=0.25, OnlyWhenAiming=false}\n\tlocal paCurrentOffset = 0\n\tlocal paTargetOffset = 0\n\n\tfunction PeekAssistTick()\n\t\tif not PeekAssistSettings.Enabled then\n\t\t\tpaTargetOffset = 0\n\t\telse\n\t\t\tif PeekAssistSettings.OnlyWhenAiming and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then\n\t\t\t\tpaTargetOffset = 0\n\t\t\telseif UserInputService:IsKeyDown(PeekAssistSettings.KeyLeft) then\n\t\t\t\tpaTargetOffset = -PeekAssistSettings.Offset\n\t\t\telseif UserInputService:IsKeyDown(PeekAssistSettings.KeyRight) then\n\t\t\t\tpaTargetOffset = PeekAssistSettings.Offset\n\t\t\telse\n\t\t\t\tpaTargetOffset = 0\n\t\t\tend\n\t\tend\n\t\tpaCurrentOffset = paCurrentOffset + (paTargetOffset - paCurrentOffset) * PeekAssistSettings.Smoothness\n\t\tif math.abs(paCurrentOffset) > 0.01 then\n\t\t\tlocal cam = workspace.CurrentCamera\n\t\t\tcam.CFrame = cam.CFrame + cam.CFrame.RightVector * paCurrentOffset\n\t\tend\n\tend\n\nRunService.RenderStepped:Connect(function()\n    if FakeDuckSettings.Enabled then\n        local ok, err = pcall(FakeDuckTick)\n        if not ok then warn("[FakeDuck]", err) end\n    end\n    if PeekAssistSettings.Enabled then\n        local ok, err = pcall(PeekAssistTick)\n        if not ok then warn("[Peek]", err) end\n    end\nend)\n\n\tAntiKickSettings = {\n\t\tEnabled = true,\n\t\tBlockPlayerKick = true,\n\t\tBlockNamecallKick = true,\n\t\tBlockCoreKick = true,\n\t\tBlockVoteKick = false,\n\t}\n\n\tpcall(function()\n\t\tlocal oldKick = LocalPlayer.Kick\n\t\thookfunction(LocalPlayer.Kick, function(self, ...)\n\t\t\tif AntiKickSettings.Enabled and AntiKickSettings.BlockPlayerKick then\n\t\t\t\twarn("[AntiKick] LocalPlayer:Kick BLOCKED → " .. tostring(...))\n\t\t\t\treturn\n\t\t\tend\n\t\t\treturn oldKick(self, ...)\n\t\tend)\n\tend)\n\n\tif AntiKickSettings.BlockVoteKick then\n\t\ttask.spawn(function()\n\t\t\tlocal RS = game:GetService("ReplicatedStorage")\n\t\t\tlocal vk = RS:WaitForChild("NetworkRemotes", 5)\n\t\t\tvk = vk and vk:WaitForChild("VoteKick", 5)\n\t\t\tif not vk then return end\n\t\t\tfor _, r in ipairs(vk:GetChildren()) do\n\t\t\t\tpcall(function()\n\t\t\t\t\tr.OnClientEvent:Connect(function(...)\n\t\t\t\t\t\twarn("[AntiKick] VoteKick event: " .. r.Name .. " args: " .. tostring(...))\n\t\t\t\t\tend)\n\t\t\t\tend)\n\t\t\tend\n\t\tend)\n\tend\n\n\tprint("[AntiKick] Loaded")\n\n\tlocal BHopEnabled = false\n\tlocal BHopAutoJump = true\n\tlocal BHopKey = Enum.KeyCode.Space\n\tlocal BHOP_MAX_SPEED = 28\n\tlocal BHOP_BOOST = 0.4\n\n\tfunction tick_bhop()\n\t\tif not BHopEnabled then return end\n\t\tif not UserInputService:IsKeyDown(BHopKey) then return end\n\t\tlocal char = LocalPlayer.Character\n\t\tif not char then return end\n\t\tlocal hum = char:FindFirstChildOfClass("Humanoid")\n\t\tif not hum or hum.Health <= 0 then return end\n\t\tlocal hrp = char:FindFirstChild("HumanoidRootPart")\n\t\tif not hrp then return end\n\t\tif char:GetAttribute("Dead") then return end\n\n\t\tif hum.FloorMaterial ~= Enum.Material.Air then\n\t\t\thum:ChangeState(Enum.HumanoidStateType.Jumping)\n\t\telse\n\t\t\tlocal vel = hrp.AssemblyLinearVelocity\n\t\t\tlocal hVel = Vector3.new(vel.X, 0, vel.Z)\n\t\t\tlocal hSpeed = hVel.Magnitude\n\t\t\tif hSpeed > 0.1 and hSpeed < BHOP_MAX_SPEED then\n\t\t\t\tlocal dir = hVel.Unit\n\t\t\t\tlocal newSpeed = math.min(hSpeed + BHOP_BOOST, BHOP_MAX_SPEED)\n\t\t\t\thrp.AssemblyLinearVelocity = Vector3.new(dir.X * newSpeed, vel.Y, dir.Z * newSpeed)\n\t\t\tend\n\t\tend\n\tend\n\n\tRunService.Heartbeat:Connect(tick_bhop)\n\n\tlocal SilentAimSettings = {Enabled=false, TeamCheck=false, VisibleCheck=false, FOVRadius=130, FOVVisible=false, HitChance=100}\n\n\tlocal Snow = {\n\t\tEnabled = false,\n\t\tRadius = 60,\n\t\tDensity = 300,\n\t\tSpeed = 8,\n\t\tSize = 0.4,\n\t\tColor = Color3.fromRGB(255,255,255),\n\t\tTransparency = 0.15,\n\t}\n\n\tlocal SnowPart, SnowEmitter = nil, nil\n\n\tfunction SnowEnsure()\n\t\tif SnowPart and SnowPart.Parent then return end\n\t\tSnowPart = Instance.new("Part")\n\t\tSnowPart.Name = "MonotonSnow"\n\t\tSnowPart.Anchored = true\n\t\tSnowPart.CanCollide = false\n\t\tSnowPart.CanQuery = false\n\t\tSnowPart.CanTouch = false\n\t\tSnowPart.CastShadow = false\n\t\tSnowPart.Transparency = 1\n\t\tSnowPart.Size = Vector3.new(1,1,1)\n\t\tSnowPart.Parent = workspace\n\n\t\tSnowEmitter = Instance.new("ParticleEmitter")\n\t\tSnowEmitter.Name = "Snow"\n\t\tSnowEmitter.Texture = "rbxassetid://6042053626"\n\t\tSnowEmitter.LightEmission = 0.05\n\t\tSnowEmitter.LightInfluence = 0.3\n\t\tSnowEmitter.Shape = Enum.ParticleEmitterShape.Box\n\t\tSnowEmitter.ShapeInOut = Enum.ParticleEmitterShapeInOut.InOut\n\t\tSnowEmitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\t\tSnowEmitter.EmissionDirection = Enum.NormalId.Bottom\n\t\tSnowEmitter.SpreadAngle = Vector2.new(20, 20)\n\t\tSnowEmitter.Rotation = NumberRange.new(0, 360)\n\t\tSnowEmitter.RotSpeed = NumberRange.new(-45, 45)\n\t\tSnowEmitter.VelocityInheritance = 0\n\t\tSnowEmitter.Acceleration = Vector3.new(0, -3, 0)\n\t\tSnowEmitter.Drag = 1.5\n\t\tSnowEmitter.Parent = SnowPart\n\tend\n\n\tfunction SnowUpdate()\n\t\tif not Snow.Enabled then\n\t\t\tif SnowPart then SnowPart:Destroy(); SnowPart = nil; SnowEmitter = nil end\n\t\t\treturn\n\t\tend\n\t\tSnowEnsure()\n\t\tlocal char = LocalPlayer.Character\n\t\tlocal root = char and char:FindFirstChild("HumanoidRootPart")\n\t\tif not root then return end\n\n\t\tSnowPart.Size = Vector3.new(Snow.Radius * 2, 1, Snow.Radius * 2)\n\t\tSnowPart.CFrame = CFrame.new(root.Position + Vector3.new(0, Snow.Radius * 0.6, 0))\n\n\t\tlocal fallTime = Snow.Radius / math.max(Snow.Speed, 0.1)\n\t\tSnowEmitter.Rate = Snow.Density\n\t\tSnowEmitter.Lifetime = NumberRange.new(fallTime * 0.8, fallTime * 1.2)\n\t\tSnowEmitter.Speed = NumberRange.new(Snow.Speed * 0.7, Snow.Speed * 1.3)\n\t\tSnowEmitter.Size = NumberSequence.new({\n\t\t\tNumberSequenceKeypoint.new(0, Snow.Size * 0.5),\n\t\t\tNumberSequenceKeypoint.new(1, Snow.Size),\n\t\t})\n\t\tSnowEmitter.Transparency = NumberSequence.new({\n\t\t\tNumberSequenceKeypoint.new(0, 1),\n\t\t\tNumberSequenceKeypoint.new(0.05, Snow.Transparency),\n\t\t\tNumberSequenceKeypoint.new(0.9, Snow.Transparency),\n\t\t\tNumberSequenceKeypoint.new(1, 1),\n\t\t})\n\t\tSnowEmitter.Color = ColorSequence.new(Snow.Color)\n\tend\n\n\ttask.spawn(function()\n    while task.wait(0.05) do\n        if Snow.Enabled then SnowUpdate() end\n    end\nend)\n\n\tlocal spinAngle = 0\n\tlocal randomYaw = 0\n\tlocal lastRandomUpdate = 0\n\n\tlocal AntiaimSettings = {\n\t\tEnabled = false,\n\t\tYawMode = "Backward (180)",\n\t\tSpinSpeed = 10,\n\t\tRandomInterval = 0.5,\n\t\tPitchMode = "Down (-1)",\n\t}\n\tlocal AA_Hooked = false\n\n\tfunction InitAntiaimHook()\n\t\tif AA_Hooked then return true end\n\t\tlocal ok, RemotesModule = pcall(function()\n\t\t\treturn require(game:GetService("ReplicatedStorage").Database.Security.Remotes)\n\t\tend)\n\t\tif not ok or not RemotesModule then\n\t\t\twarn("[AA] Remotes module not found")\n\t\t\treturn false\n\t\tend\n\t\tlocal lookRemote = RemotesModule.Character and RemotesModule.Character.UpdateLookAngle\n\t\tif not lookRemote or not lookRemote.Send then\n\t\t\twarn("[AA] UpdateLookAngle remote not found")\n\t\t\treturn false\n\t\tend\n\n\t\tlocal OriginalSendLook = lookRemote.Send\n\t\tlocal hooked = function(...)\n\t\t\tlocal args = select(1, ...)\n\t\t\tif AntiaimSettings.Enabled and typeof(args) == "table" and args.HorizontalAngle then\n\t\t\t\tlocal yaw = args.HorizontalAngle\n\t\t\t\tlocal mode = AntiaimSettings.YawMode\n\n\t\t\t\tif mode == "Backward (180)" then\n\t\t\t\t\tyaw = yaw + math.pi\n\t\t\t\telseif mode == "Left (90)" then\n\t\t\t\t\tyaw = yaw + math.pi / 2\n\t\t\t\telseif mode == "Right (-90)" then\n\t\t\t\t\tyaw = yaw - math.pi / 2\n\t\t\t\telseif mode == "Spin" then\n\t\t\t\t\tspinAngle = (spinAngle + (AntiaimSettings.SpinSpeed * 0.01)) % (2 * math.pi)\n\t\t\t\t\tyaw = yaw + spinAngle\n\t\t\t\telseif mode == "Random" then\n\t\t\t\t\tif tick() - lastRandomUpdate > AntiaimSettings.RandomInterval then\n\t\t\t\t\t\trandomYaw = (math.random() - 0.5) * 2 * math.pi\n\t\t\t\t\t\tlastRandomUpdate = tick()\n\t\t\t\t\tend\n\t\t\t\t\tyaw = randomYaw\n\t\t\t\tend\n\n\t\t\t\tyaw = (yaw + math.pi) % (2 * math.pi) - math.pi\n\t\t\t\targs.HorizontalAngle = yaw\n\n\t\t\t\tlocal pm = AntiaimSettings.PitchMode\n\t\t\t\tif pm == "Down (-1)" then args.VerticalLook = -1\n\t\t\t\telseif pm == "Up (1)" then args.VerticalLook = 1\n\t\t\t\telseif pm == "Zero (0)" then args.VerticalLook = 0\n\t\t\t\telseif pm == "Random" then args.VerticalLook = (math.random() - 0.5) * 2\n\t\t\t\tend\n\t\t\tend\n\t\t\treturn OriginalSendLook(...)\n\t\tend\n\n\t\tif newcclosure then\n\t\t\tlookRemote.Send = newcclosure(hooked)\n\t\telse\n\t\t\tlookRemote.Send = hooked\n\t\tend\n\t\tAA_Hooked = true\n\t\tprint("[AA] Hooked UpdateLookAngle")\n\t\treturn true\n\tend\n\n    \t-- ============================================================\n\t--  KILL SOUND\n\t-- ============================================================\n\tlocal KillSoundSettings = {\n\t\tEnabled = false,\n\t\tSoundId = "rbxassetid://91146616687345",\n\t\tVolume = 5,\n\t}\n\n\tlocal KillSounds = {\n\t\t["Headshot"]   = "rbxassetid://91146616687345",\n\t\t["Skeet"]      = "rbxassetid://4817809188",\n\t\t["Neverlose"]  = "rbxassetid://8726881116",\n\t\t["Rust"]       = "rbxassetid://1255040462",\n\t\t["Bubble"]     = "rbxassetid://198598793",\n\t\t["Ding"]       = "rbxassetid://2868331684",\n\t\t["TF2"]        = "rbxassetid://8255306220",\n\t\t["CS:GO"]      = "rbxassetid://70242316792718",\n\t}\n\n\tfunction PlayKillSound()\n\t\tif not KillSoundSettings.Enabled then return end\n\t\tlocal snd = Instance.new("Sound")\n\t\tsnd.SoundId = KillSoundSettings.SoundId\n\t\tsnd.Volume = KillSoundSettings.Volume\n\t\tsnd.Parent = SoundService\n\t\tsnd:Play()\n\t\tDebris:AddItem(snd, 3)\n\tend\n\n    \t-- ============================================================\n\t--  KILL SOUND TRIGGER — ловит все киллы (не только silent aim)\n\t-- ========