,255), Transparency=0}\n\tlocal HandChams = {Enabled=false, Transparency=0.5, Color=nil}\n\tlocal originalToolParts = {}\n\tlocal originalHandParts = {}\n\n\tlocal WeaponChams = {\n\t\tEnabled = false,\n\t\tColor = Color3.fromRGB(0, 255, 255),\n\t\tTransparency = 0,\n\t\tNeon = true,\n\t}\n\tlocal weaponOriginal = {}\n\n\tfunction isSkippableWeaponPart(part)\n\t\tlocal n = string.lower(part.Name)\n\t\tif n:find("light") or n:find("camera") or n:find("muzzle") or n:find("flash") then return true end\n\t\tfor _, c in ipairs(part:GetChildren()) do\n\t\t\tif c:IsA("Light") then return true end\n\t\t\tif c:IsA("ParticleEmitter") or c:IsA("Smoke") or c:IsA("Fire") then return true end\n\t\tend\n\t\treturn false\n\tend\n\n\tfunction applyWeaponChams()\n\t\tlocal char = LocalPlayer.Character\n\t\tif not char then return end\n\t\tlocal tool = char:FindFirstChildOfClass("Tool")\n\t\tif not tool then return end\n\t\tfor _, part in ipairs(tool:GetDescendants()) do\n\t\t\tif part:IsA("BasePart") then\n\t\t\t\tif isSkippableWeaponPart(part) then\n\t\t\t\t\tif weaponOriginal[part] then\n\t\t\t\t\t\tlocal o = weaponOriginal[part]\n\t\t\t\t\t\tpart.Material = o.Material\n\t\t\t\t\t\tpart.Color = o.Color\n\t\t\t\t\t\tpart.Transparency = o.Transparency\n\t\t\t\t\t\tweaponOriginal[part] = nil\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\tif not weaponOriginal[part] then\n\t\t\t\t\t\tweaponOriginal[part] = {\n\t\t\t\t\t\t\tMaterial = part.Material,\n\t\t\t\t\t\t\tColor = part.Color,\n\t\t\t\t\t\t\tTransparency = part.Transparency,\n\t\t\t\t\t\t}\n\t\t\t\t\tend\n\t\t\t\t\tif WeaponChams.Neon then\n\t\t\t\t\t\tpart.Material = Enum.Material.Neon\n\t\t\t\t\tend\n\t\t\t\t\tpart.Color = WeaponChams.Color\n\t\t\t\t\tpart.Transparency = WeaponChams.Transparency\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tfunction restoreWeaponChams()\n\t\tfor part, orig in pairs(weaponOriginal) do\n\t\t\tif part and part.Parent then\n\t\t\t\tpart.Material = orig.Material\n\t\t\t\tpart.Color = orig.Color\n\t\t\t\tpar