\tMaterial = Enum.Material.ForceField,\n\t\tOffsetZ = 0,\n\t\tOffsetY = 0,\n\t\tGhost = nil,\n\t\tPartMap = {},\n\t\tRealMap = {},\n\t\tFakeRoot = nil,\n\t}\n\n\tfunction destroyGhost()\n\t\tif DesyncSelf.Ghost then DesyncSelf.Ghost:Destroy() end\n\t\tDesyncSelf.Ghost = nil\n\t\tDesyncSelf.PartMap = {}\n\t\tDesyncSelf.RealMap = {}\n\t\tDesyncSelf.FakeRoot = nil\n\tend\n\n\tfunction buildGhost()\n\t\tdestroyGhost()\n\t\tlocal char = LocalPlayer.Character\n\t\tif not char then return end\n\t\tlocal root = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart\n\t\tif not root then return end\n\n\t\tlocal ghost = Instance.new("Model")\n\t\tghost.Name = "MonotonDesyncGhost"\n\n\t\tlocal fakeRoot = Instance.new("Part")\n\t\tfakeRoot.Name = "HumanoidRootPart"\n\t\tfakeRoot.Size = root.Size\n\t\tfakeRoot.CFrame = root.CFrame\n\t\tfakeRoot.Anchored = true\n\t\tfakeRoot.CanCollide = false\n\t\tfakeRoot.CanQuery = false\n\t\tfakeRoot.CanTouch = false\n\t\tfakeRoot.CastShadow = false\n\t\tfakeRoot.Transparency = DesyncSelf.Transparency\n\t\tfakeRoot.Color = DesyncSelf.Color\n\t\tfakeRoot.Material = DesyncSelf.Material\n\t\tfakeRoot.Parent = ghost\n\t\tghost.PrimaryPart = fakeRoot\n\n\t\tfor _, d in ipairs(char:GetDescendants()) do\n\t\t\tif d:IsA("BasePart") and d ~= root and d.Name ~= "HumanoidRootPart" then\n\t\t\t\tlocal fake = Instance.new("Part")\n\t\t\t\tfake.Name = d.Name\n\t\t\t\tfake.Size = d.Size\n\t\t\t\tfake.Anchored = false\n\t\t\t\tfake.CanCollide = false\n\t\t\t\tfake.CanQuery = false\n\t\t\t\tfake.CanTouch = false\n\t\t\t\tfake.CastShadow = false\n\t\t\t\tfake.Massless = true\n\t\t\t\tfake.Transparency = DesyncSelf.Transparency\n\t\t\t\tfake.Color = DesyncSelf.Color\n\t\t\t\tfake.Material = DesyncSelf.Material\n\t\t\t\tfake.CFrame = d.CFrame\n\t\t\t\tfake.Parent = ghost\n\n\t\t\t\tlocal weld = Instance.new("WeldConstraint")\n\t\t\t\tweld.Part0 = fakeRoot\n\t\t\t\tweld.Part1 = fake\n\t\t\t\tweld.Parent = fake\n\n\t\t\t\tDesyncSelf.PartMap[fake] = d\n\t\t\tend\n\t\tend\n\n\t\tghost.Parent = workspace\n\t\tDesyncSelf.Ghost = ghost\n\t\tDesyncSelf.FakeRoot = fakeRoot\n\tend\n\n\tlocal function applyGhostStyle()\n\t\tlocal ghost = DesyncSelf.Ghost\n\t\tif not ghost then return end\n\t\tfor _, p in ipairs(ghost:GetDescendants()) do\n\t\t\tif p:IsA("BasePart") then\n\t\t\t\tp.Transparency = DesyncSelf.Transparency\n\t\t\t\tp.Color = DesyncSelf.Color\n\t\t\t\tp.Material = DesyncSelf.Material\n\t\t\tend\n\t\tend\n\tend\n\n\tlocal function updateGhost()\n\t\tif not DesyncSelf.Enabled then\n\t\t\tif DesyncSelf.Ghost then destroyGhost() end\n\t\t\treturn\n\t\tend\n\t\tlocal char = LocalPlayer.Character\n\t\tif not char then\n\t\t\tif DesyncSelf.Ghost then destroyGhost() end\n\t\t\treturn\n\t\tend\n\t\tif not DesyncSelf.Ghost or not DesyncSelf.Ghost.Parent then\n\t\t\tbuildGhost()\n\t\tend\n\t\tlocal root = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart\n\t\tlocal fakeRoot = DesyncSelf.FakeRoot\n\t\tif not root or not fakeRoot or not fakeRoot.Parent then return end\n\n\t\tlocal offset = CFrame.new(0, DesyncSelf.OffsetY, -DesyncSelf.OffsetZ)\n\t\tfakeRoot.CFrame = root.CFrame * offset\n\tend\nRunService.RenderStepped:Connect(function()\n    if DesyncSelf.Enabled then\n        updateGhost()\n    end\nend)\n\tLocalPlayer.CharacterAdded:Connect(function()\n\t\ttask.wait(0.5)\n\t\tif DesyncSelf.Ghost then destroyGhost() end\n\t\tif DesyncSelf.Enabled then buildGhost() end\n\tend)\n\tlocal ThirdPersonSettings = {Enabled=false, Distance=8, HeightOffset=2, Key=Enum.KeyCode.V, NoClip=true}\n\n\tlocal NightSettings = {Enabled=false, OldClock=14.5, OldAmbient=Lighting.Ambient, OldOutdoor=Lighting.OutdoorAmbient, OldBright=Lighting.Brightness}\n\n\tlocal TargetBoxSettings = {\n\t\tEnabled = true, Size = 14, Thickness = 2, Spin = 0, Glow = true,\n\t\tVisibleColor = Color3.fromRGB(60, 255, 60),\n\t\tBlockedColor = Color3.fromRGB(255, 60, 60),\n\t\tNeutralColor = Color3.fromRGB(160, 160, 160),\n\t}\n\tlocal TargetBox = {\n\t\tOutline = Drawing.new("Square"), Fill = Drawing.new("Square"),\n\t\tGlow = Drawing.new("Square"), SpinAngle = 0, SpinLines = nil,\n\t}\n\tTargetBox.Outline.Thickness = TargetBoxSettings.Thickness\n\tTargetBox.Outline.Filled = false; TargetBox.Outline.Transparency = 1\n\tTargetBox.Outline.ZIndex = 1001; TargetBox.Outline.Visible = false\n\tTargetBox.Fill.Filled = true; TargetBox.Fill.Transparency = 0.75\n\tTargetBox.Fill.ZIndex = 1000; TargetBox.Fill.Visible = false\n\tTargetBox.Glow.Filled = true; TargetBox.Glow.Transparency = 0.9\n\tTargetBox.Glow.ZIndex = 999; TargetBox.Glow.Visible = false\n\n\tlocal WeaponSettings = {NoRecoil=false, NoSpread=false, NoKick=false, InfAmmo=false, RefillDelay=0}\n\n\tlocal PenSettings = {Enabled=false, Penetration=1.0, ArmorPen=1.0, Wallbang=1.0}\n\tlocal PenOriginal = {}\n\n\tlocal function BS_applyPenRate()\n\t\tlocal RS = game:GetService("ReplicatedStorage")\n\t\tlocal DB = RS:FindFirstChild("Database")\n\t\tlocal Custom = DB and DB:FindFirstChild("Custom")\n\t\tlocal Weapons = Custom and Custom:FindFirstChild("Weapons")\n\t\tif not Weapons then return 0 end\n\t\tlocal patched = 0\n\t\tfor _, weapon in ipairs(Weapons:GetChildren()) do\n\t\t\tfor _, field in ipairs({"Penetration","ArmorPenetration","WallbangMultiplier"}) do\n\t\t\t\tlocal v = weapon:FindFirstChild(field)\n\t\t\t\tif v and v:IsA("NumberValue") then\n\t\t\t\t\tif not PenOriginal[weapon] then PenOriginal[weapon] = {} end\n\t\t\t\t\tif PenOriginal[weapon][field] == nil then PenOriginal[weapon][field] = v.Value end\n\t\t\t\t\tlocal base = PenOriginal[weapon][field]\n\t\t\t\t\tif field == "Penetration" then\n\t\t\t\t\t\tv.Value = math.clamp(base * PenSettings.Penetration, 0, 5)\n\t\t\t\t\telseif field == "ArmorPenetration" then\n\t\t\t\t\t\tv.Value = math.clamp(base * PenSettings.ArmorPen, 0, 1)\n\t\t\t\t\telseif field == "WallbangMultiplier" then\n\t\t\t\t\t\tv.Value = math.clamp(base * PenSettings.Wallbang, 0, 5)\n\t\t\t\t\tend\n\t\t\t\t\tpatched = patched + 1\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\treturn patched\n\tend\n\n\tfunction BS_restorePenRate()\n\t\tfor weapon, fields in pairs(PenOriginal) do\n\t\t\tif weapon and weapon.Parent then\n\t\t\t\tfor field, val in pairs(fields) do\n\t\t\t\t\tlocal v = weapon:FindFirstChild(field)\n\t\t\t\t\tif v and v:IsA("NumberValue") then v.Value = val end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tPenOriginal = {}\n\tend\n\tlocal BS_refillConn = nil\n\tlocal BS_recoilApplied = false\n\n\tlocal MovementV2 = game:GetService("ReplicatedStorage"):FindFirstChild("MovementV2")\n\tlocal SpeedProfile = MovementV2 and MovementV2:FindFirstChild("SpeedProfile")\n\tlocal WalkSettings = {Enabled=false, Value=32}\n\tlocal ProfileSettings = {Enabled=false, Value=40}\n\tlocal Bhop2Settings = {Enabled=false, Key=Enum.KeyCode.Space}\n\tlocal SpeedProfileData = nil\n\tpcall(function() if SpeedProfile then SpeedProfileData = require(SpeedProfile) end end)\n\n\tfunction applySpeedProfileHack()\n\t\tif not ProfileSettings.Enabled then return end\n\t\tif SpeedProfileData and type(SpeedProfileData) == "table" then\n\t\t\tfor k, _ in pairs(SpeedProfileData) do\n\t\t\t\tlocal low = string.lower(tostring(k))\n\t\t\t\tif string.find(low, "walk", 1, true) or string.find(low, "sprint", 1, true) then\n\t\t\t\t\tpcall(function() SpeedProfileData[k] = ProfileSettings.Value end)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tif SpeedProfile then\n\t\t\tfor _, c in ipairs(SpeedProfile:GetDescendants()) do\n\t\t\t\tif c:IsA("NumberValue") then\n\t\t\t\t\tlocal low = string.lower(c.Name)\n\t\t\t\t\tif string.find(low, "walk", 1, true) or string.find(low, "sprint", 1, true) then c.Value = ProfileSettings.Value end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tlocal WalkOriginal = 16\n\tLocalPlayer.CharacterAdded:Connect(function(char)\n\t\ttask.wait(0.5); local hum = char:FindFirstChildOfClass("Humanoid")\n\t\tif hum then WalkOriginal = hum.WalkSpeed end\n\tend)\n\tif LocalPlayer.Character then\n\t\tlocal hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")\n\t\tif hum then WalkOriginal = hum.WalkSpeed end\n\tend\n\n\tlocal autoJumpConn = nil\n\tfunction startAutoJump()\n\t\tif autoJumpConn then return end\n\t\tautoJumpConn = RunService.Heartbeat:Connect(function()\n\t\t\tlocal char = LocalPlayer.Character\n\t\t\tif not char then return end\n\t\t\tlocal hum = char:FindFirstChildOfClass("Humanoid")\n\t\t\tif not hum or hum.Health <= 0 then return end\n\t\t\tif UserInputService:IsKeyDown(AutoJumpSettings.Key) then\n\t\t\t\tif hum.FloorMaterial ~= Enum.Material.Air then\n\t\t\t\t\thum.Jump = true\n\t\t\t\t\tif hum:GetState() == Enum.HumanoidStateType.Jumping then hum:ChangeState(Enum.HumanoidStateType.Jumping) end\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\tend\n\tfunction stopAutoJump()\n\t\tif autoJumpConn then autoJumpConn:Disconnect(); autoJumpConn = nil end\n\tend\n\n\tfunction getPlayerTeam(p)\n\t\tif not p then return nil end\n\t\tif p == LocalPlayer then return "Me" end\n\n\t\tlocal myTeam = LocalPlayer:GetAttribute("Team")\n\t\tif not myTeam then\n\t\t\tlocal mc = LocalPlayer.Character\n\t\t\tif mc then\n\t\t\t\tmyTeam = mc:GetAttribute("Team")\n\t\t\t\tif not myTeam then\n\t\t\t\t\tlocal mroot = mc:FindFirstChild("HumanoidRootPart")\n\t\t\t\t\tif mroot then myTeam = mroot:GetAttribute("Team") end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\tlocal theirTeam = p:GetAttribute("Team")\n\t\tif not theirTeam then\n\t\t\tlocal c = p.Character\n\t\t\tif c then\n\t\t\t\ttheirTeam = c:GetAttribute("Team")\n\t\t\t\tif not theirTeam then\n\t\t\t\t\tlocal root = c:FindFirstChild("HumanoidRootPart")\n\t\t\t\t\tif root then theirTeam = root:GetAttribute("Team") end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\tif myTeam and theirTeam and myTeam == theirTeam then return "Ally" end\n\t\treturn "Enemy"\n\tend\n\n\tfunction isVisible(targetPart)\n\t\tif not targetPart or not targetPart.Parent then return false end\n\t\tlocal params = RaycastParams.new()\n\t\tparams.FilterType = Enum.RaycastFilterType.Exclude\n\t\tparams.IgnoreWater = true\n\t\tparams.FilterDescendantsInstances = LocalPlayer.Character and {LocalPlayer.Character} or {}\n\t\tlocal origin = Camera.CFrame.Position\n\t\tlocal result = Workspace:Raycast(origin, targetPart.Position - origin, params)\n\t\tif not result then return true end\n\t\tlocal model = result.Instance and result.Instance:FindFirstAncestorOfClass("Model")\n\t\treturn model and Players:GetPlayerFromCharacter(model) ~= nil\n\tend\n\n\tlocal AimSettings = {MinDamage=0, Priority="Best Hit", UseAllParts=false, HitParts={"Head"}}\n\tlocal ALL_BODY_PARTS = {\n\t\t"Head","UpperTorso","LowerTorso","Torso","HumanoidRootPart",\n\t\t"LeftUpperArm","RightUpperArm","LeftLowerArm","RightLowerArm",\n\t\t"LeftHand","RightHand","Left Arm","Right Arm",\n\t\t"LeftUpperLeg","RightUpperLeg","LeftLowerLeg","RightLowerLeg",\n\t\t"LeftFoot","RightFoot","Left Leg","Right Leg",\n\t}\n\tlocal DAMAGE_MULTIPLIER = {\n\t\tHead=4, HumanoidRootPart=1, UpperTorso=1, LowerTorso=1, Torso=1,\n\t\tLeftUpperArm=0.66, RightUpperArm=0.66, LeftLowerArm=0.5, RightLowerArm=0.5,\n\t\tLeftHand=0.5, RightHand=0.5, ["Left Arm"]=0.66, ["Right Arm"]=0.66,\n\t\tLeftUpperLeg=0.75, RightUpperLeg=0.75, LeftLowerLeg=0.5, RightLowerLeg=0.5,\n\t\tLeftFoot=0.5, RightFoot=0.5, ["Left Leg"]=0.75, ["Right Leg"]=0.75,\n\t}\n\tfunction getWeaponBaseDamage()\n\t\tlocal char = LocalPlayer.Character\n\t\tlocal tool = char and char:FindFirstChildOfClass("Tool")\n\t\tif not tool then return 30 end\n\t\tlocal d = tool:FindFirstChild("Damage")\n\t\tif d and d:IsA("NumberValue") then return d.Value end\n\t\tif tool:GetAttribute("Damage") then return tool:GetAttribute("Damage") end\n\t\treturn 30\n\tend\n\tfunction getActiveParts(char)\n\t\tlocal parts = {}\n\t\tif AimSettings.UseAllParts then\n\t\t\tfor _, n in ipairs(ALL_BODY_PARTS) do\n\t\t\t\tlocal p = char:FindFirstChild(n)\n\t\t\t\tif p and p:IsA("BasePart") then parts[n] = p end\n\t\t\tend\n\t\telse\n\t\t\tfor _, n in ipairs(AimSettings.HitParts) do\n\t\t\t\tlocal p = char:FindFirstChild(n)\n\t\t\t\tif p and p:IsA("BasePart") then parts[n] = p end\n\t\t\tend\n\t\tend\n\t\treturn parts\n\tend\n\tfunction getBestTarget(useVisible, fov, teamCheck)\n\t\tlocal center = Camera.ViewportSize / 2\n\t\tlocal baseDmg = getWeaponBaseDamage()\n\t\tlocal bestPart, bestScore = nil, -math.huge\n\t\tlocal myTeam = LocalPlayer:GetAttribute("Team")\n\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\tif player == LocalPlayer then continue end\n\t\t\tlocal char = player.Character\n\t\t\tif not char or char:GetAttribute("Dead") then continue end\n\t\t\tif myTeam then\n\t\t\t\tlocal theirTeam = player:GetAttribute("Team")\n\t\t\t\tif theirTeam and theirTeam == myTeam then continue end\n\t\t\tend\n\t\t\tlocal parts = getActiveParts(char)\n\t\t\tfor partName, part in pairs(parts) do\n\t\t\t\tif useVisible and not isVisible(part) then continue end\n\t\t\t\tlocal sp, on = Camera:WorldToViewportPoint(part.Position)\n\t\t\t\tif not on then continue end\n\t\t\t\tlocal dmg = (DAMAGE_MULTIPLIER[partName] or 1) * baseDmg\n\t\t\t\tif dmg < AimSettings.MinDamage then continue end\n\t\t\t\tlocal screenDist = (Vector2.new(sp.X, sp.Y) - center).Magnitude\n\t\t\t\tif fov and screenDist > fov then continue end\n\t\t\t\tlocal worldDist = (Camera.CFrame.Position - part.Position).Magnitude\n\t\t\t\tlocal score\n\t\t\t\tif AimSettings.Priority == "Best Hit" then score = -screenDist\n\t\t\t\telseif AimSettings.Priority == "Best Damage" then score = dmg * 100 - screenDist\n\t\t\t\telseif AimSettings.Priority == "Nearest" then score = -worldDist\n\t\t\t\tend\n\t\t\t\tif score > bestScore then bestScore = score; bestPart = part end\n\t\t\tend\n\t\tend\n\t\treturn bestPart\n\tend\n\tfunction GetSilentTarget()\n\t\treturn getBestTarget(SilentAimSettings.VisibleCheck, SilentAimSettings.FOVRadius, SilentAimSettings.TeamCheck)\n\tend\n\t-- ============================================================\n\t--  RAGEBOT — из Radon (Obsidian-based)\n\t-- ============================================================\n\tlocal RagebotSettings = {Enabled=false, TeamCheck=true, HitPart="Head", FOV=200, FireRate=0.05}\n\tlocal MultiShotSettings = {Enabled=true, Count=3}\n\n\t-- Объект оружия (Weapon:shoot())\n\tlocal getCurrentEquipped = nil\n\tpcall(function()\n\t\tfor _, obj in next, getgc(true) do\n\t\t\tif type(obj) == "table" and rawget(obj, "getCurrentEquipped") then\n\t\t\t\tgetCurrentEquipped = obj.getCurrentEquipped\n\t\t\t\tbreak\n\t\t\tend\n\t\tend\n\tend)\n\n\tfunction getEquipped()\n\t\tif not getCurrentEquipped then return nil end\n\t\tlocal success, result = pcall(function()\n\t\t\treturn debug.getupvalue(getCurrentEquipped, 1).CurrentEquipped\n\t\tend)\n\t\tif not success then return nil end\n\t\treturn result\n\tend\n\n\tlocal Weapon = nil\n\ttask.spawn(function()\n\t\twhile task.wait(0.5) do\n\t\t\tpcall(function()\n\t\t\t\tif getEquipped then\n\t\t\t\t\tWeapon = getEquipped()\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\tend)\n\n\t-- === Целевая функция ===\n\tfunction GetRagebotTarget()\n\t\tlocal center = Camera.ViewportSize / 2\n\t\tlocal bestPart, bestScore = nil, -math.huge\n\t\tlocal myTeam = LocalPlayer:GetAttribute("Team")\n\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\tif player == LocalPlayer then continue end\n\t\t\tlocal char = player.Character\n\t\t\tif not char or char:GetAttribute("Dead") then continue end\n\t\t\tif RagebotSettings.TeamCheck and getPlayerTeam(player) == "Ally" then continue end\n\t\t\tlocal part = char:FindFirstChild(RagebotSettings.HitPart) or char:FindFirstChild("Head")\n\t\t\tif not part then continue end\n\t\t\tlocal sp, on = Camera:WorldToViewportPoint(part.Position)\n\t\t\tif not on then continue end\n\t\t\tlocal dist = (Vector2.new(sp.X, sp.Y) - center).Magnitude\n\t\t\tif dist > RagebotSettings.FOV then continue end\n\t\t\tlocal score = -dist\n\t\t\tif score > bestScore then bestScore = score; bestPart = part end\n\t\tend\n\t\treturn bestPart\n\tend\n\n\t-- === Loop стрельбы ===\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(RagebotSettings.FireRate or 0.05)\n\t\t\tif RagebotSettings.Enabled and Weapon and Weapon.IsEquipped and Weapon.Rounds > 0 then\n\t\t\t\tlocal target = GetRagebotTarget()\n\t\t\t\tif target then\n\t\t\t\t\tpcall(function() Weapon:shoot() end)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\n\n    -- ============================================================\n--  INSTANT RELOAD\n-- ============================================================\nlocal InstantReloadSettings = {Enabled = false}\n\nlocal RELOAD_ANIMS = {\n\t["Reload"]       = true,\n\t["ReloadStart"]  = true,\n\t["ReloadAction"] = true,\n\t["ReloadEnd"]    = true,\n}\nlocal RELOAD_SPEED = 199\nlocal reloadHooked = {}\n\nfunction hookAnimationReload(animModule)\n\tif not animModule or reloadHooked[animModule] then return end\n\treloadHooked[animModule] = true\n\tpcall(function()\n\t\tlocal origPlay = animModule.play\n\t\tanimModule.play = function(self_anim, animName, ...)\n\t\t\tlocal track = origPlay(self_anim, animName, ...)\n\t\t\tif track and RELOAD_ANIMS[animName] then\n\t\t\t\ttask.defer(function()\n\t\t\t\t\tpcall(function()\n\t\t\t\t\t\tif InstantReloadSettings.Enabled and track.IsPlaying then\n\t\t\t\t\t\t\ttrack:AdjustSpeed(RELOAD_SPEED)\n\t\t\t\t\t\tend\n\t\t\t\t\tend)\n\t\t\t\tend)\n\t\t\tend\n\t\t\treturn track\n\t\tend\n\tend)\nend\n\nlocal lastReloadWeapon = nil\ntask.spawn(function()\n\twhile task.wait(0.1) do\n\t\tpcall(function()\n\t\t\tif not Weapon then return end\n\t\t\tif Weapon ~= lastReloadWeapon then\n\t\t\t\tlastReloadWeapon = Weapon\n\t\t\t\tif Weapon.Viewmodel and Weapon.Viewmodel.Animation then\n\t\t\t\t\thookAnimationReload(Weapon.Viewmodel.Animation)\n\t\t\t\tend\n\t\t\t\tif Weapon.CharacterAnimator then\n\t\t\t\t\thookAnimationReload(Weapon.CharacterAnimator)\n\t\t\t\tend\n\t\t\tend\n\t\t\tif not InstantReloadSettings.Enabled then return end\n\t\t\tif Weapon.IsReloading then\n\t\t\t\tpcall(function()\n\t\t\t\t\tif Weapon.Viewmodel and Weapon.Viewmodel.Animation and Weapon.Viewmodel.Animation.Animations then\n\t\t\t\t\t\tfor name, track in pairs(Weapon.Viewmodel.Animation.Animations) do\n\t\t\t\t\t\t\tif RELOAD_ANIMS[name] and track.IsPlaying then\n\t\t\t\t\t\t\t\ttrack:AdjustSpeed(RELOAD_SPEED)\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\t\tif Weapon.CharacterAnimator and Weapon.CharacterAnimator.Animations then\n\t\t\t\t\t\tfor name, track in pairs(Weapon.CharacterAnimator.Animations) do\n\t\t\t\t\t\t\tif RELOAD_ANIMS[name] and track.IsPlaying then\n\t\t\t\t\t\t\t\ttrack:AdjustSpeed(RELOAD_SPEED)\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend)\n\t\t\tend\n\t\tend)\n\tend\nend)\n\n-- ============================================================\n--  BULLET TRACERS — при каждом выстреле (без цели)\n-- ============================================================\npcall(function()\n    local SendFunc = nil\n\n    -- Ищем функцию выстрела через getgc\n    for _, obj in next, getgc(true) do\n        if type(obj) == "table" and rawget(obj, "shoot") and typeof(obj.shoot) == "function" then\n            for _, uv in pairs(debug.getupvalues(obj.shoot)) do\n                if type(uv) == "table" and rawget(uv, "Inventory") and rawget(uv.Inventory, "ShootWeapon") then\n                    SendFunc = uv.Inventory.ShootWeapon.Send\n                    break\n                end\n            end\n        end\n        if SendFunc then break end\n    end\n\n    if not SendFunc then\n        warn("[Tracers] SendFunc не найден — трейсеры на каждый выстрел не будут работать")\n        return\n    end\n\n    local oldshoot\n    oldshoot = hookfunction(SendFunc, function(...)\n        local args = {...}\n\n        -- Рисуем трейсер для каждого патрона\n        if TracerSettings.Enabled and args[1] and type(args[1].Bullets) == "table" then\n            for _, bullet in pairs(args[1].Bullets) do\n                if type(bullet.Hits) == "table" then\n                    for _, hitData in pairs(bullet.Hits) do\n                        local endPos = hitData.Position\n                        if endPos then\n                            pcall(function()\n                                local cam = Workspace.CurrentCamera\n                                if cam then\n                                    CreateLine(cam.CFrame.Position, endPos)\n                                end\n                            end)\n                        end\n                    end\n                end\n            end\n        end\n\n        return oldshoot(unpack(args))\n    end)\n\n    print("[Tracers] Hook установлен — трейсеры работают на каждый выстрел")\nend)\n\n\tfunction CreateLine(originWorld, targetWorld)\n\t\tif not TracerSettings.Enabled then return end\n\t\tlocal startPos = originWorld - Vector3.new(0, 0.7, 0)\n\t\tlocal dist = (targetWorld - startPos).Magnitude\n\t\tif dist < 0.1 then return end\n\t\tlocal part = Instance.new("Part")\n\t\tpart.Anchored = true; part.CanCollide = false; part.CanQuery = false; part.CanTouch = false; part.CastShadow = false\n\t\tpart.Material = Enum.Material.Neon; part.Color = TracerSettings.Color\n\t\tpart.Size = Vector3.new(TracerSettings.Thickness*0.05, TracerSettings.Thickness*0.05, dist)\n\t\tpart.CFrame = CFrame.lookAt(startPos, targetWorld) * CFrame.new(0, 0, -dist/2)\n\t\tpart.Transparency = 0\n\t\tpart.Parent = workspace\n\t\tlocal fadeTime = math.max(TracerSettings.Lifetime * 0.75, 0.05)\n\t\tTweenService:Create(part, TweenInfo.new(fadeTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 1}):Play()\n\t\ttask.delay(TracerSettings.Lifetime, function()\n\t\t\tif part and part.Parent then part:Destroy() end\n\t\tend)\n\tend\n\n\tlocal WeaponHooked = false\n\tlocal RecoilHooked = false\n\tlocal SpreadHooked = false\n\n\tfunction ApplyWeaponHooks()\n\t\tlocal RS = game:GetService("ReplicatedStorage")\n\n\t\tpcall(function()\n\t\t\tlocal CC = require(RS.Controllers.CameraController)\n\t\t\tCC.weaponKick = function() end\n\t\t\tCC.setWeaponRecoil = function() end\n\t\t\tRecoilHooked = true\n\t\tend)\n\n\t\tpcall(function()\n\t\t\tlocal Bullet = require(RS.Components.Weapon.Classes.Bullet)\n\t\t\tBullet.getTrueSpread = function() return 0 end\n\t\t\tBullet.getBaseSpread = function() return 0 end\n\t\t\tBullet.getSpreadForConfig = function() return 0 end\n\n\t\t\tif not Bullet._monotonSpoofed then\n\t\t\t\tlocal OldCreate = Bullet.create\n\t\t\t\tBullet.create = function(self, aimingOptions, isAiming)\n\t\t\t\t\tif self.Spread then\n\t\t\t\t\t\tself.Spread:setPosition(0)\n\t\t\t\t\t\tself.Spread:setGoal(0)\n\t\t\t\t\tend\n\t\t\t\t\treturn OldCreate(self, aimingOptions, isAiming)\n\t\t\t\tend\n\t\t\t\tBullet._monotonSpoofed = true\n\t\t\tend\n\t\t\tSpreadHooked = true\n\t\tend)\n\n\t\tpcall(function()\n\t\t\tlocal CA = require(RS.Classes.WeaponComponent.Classes.CharacterAnimator)\n\t\t\tlocal VA = require(RS.Classes.WeaponComponent.Classes.Viewmodel.Classes.Animation)\n\t\t\tif CA and CA.playRecoil then CA.playRecoil = function() end end\n\t\t\tif VA and VA.playRecoil then VA.playRecoil = function() end end\n\t\tend)\n\n\t\tWeaponHooked = RecoilHooked or SpreadHooked\n\t\tBS_recoilApplied = WeaponHooked\n\t\treturn WeaponHooked\n\tend\n\n\tfunction BS_applyNoRecoil()\n\t\treturn ApplyWeaponHooks()\n\tend\n\n\tfunction BS_startInfAmmo()\n\t\tlocal RS = game:GetService("ReplicatedStorage")\n\t\tlocal remotes = RS:FindFirstChild("NetworkRemotes")\n\t\tlocal inv = remotes and remotes:FindFirstChild("Inventory")\n\t\tlocal refill = inv and inv:FindFirstChild("RefillAmmo")\n\t\tif not refill then return false end\n\t\tif BS_refillConn then BS_refillConn:Disconnect() end\n\t\tif WeaponSettings.RefillDelay > 0 then\n\t\t\tBS_refillConn = task.spawn(function()\n\t\t\t\twhile WeaponSettings.InfAmmo do\n\t\t\t\t\tpcall(function() refill:FireServer() end)\n\t\t\t\t\ttask.wait(WeaponSettings.RefillDelay)\n\t\t\t\tend\n\t\t\t\tBS_refillConn = nil\n\t\t\tend)\n\t\telse\n\t\t\tBS_refillConn = RunService.Heartbeat:Connect(function()\n\t\t\t\tpcall(function() refill:FireServer() end)\n\t\t\tend)\n\t\tend\n\t\treturn true\n\tend\n\n\tfunction BS_stopInfAmmo()\n\t\tif BS_refillConn then\n\t\t\tif type(BS_refillConn) == "RBXScriptConnection" then BS_refillConn:Disconnect()\n\t\t\telse pcall(task.cancel, BS_refillConn) end\n\t\t\tBS_refillConn = nil\n\t\tend\n\tend\n\n\tLocalPlayer.CharacterAdded:Connect(function()\n\t\ttask.wait(1)\n\t\tif WeaponSettings.NoRecoil or WeaponSettings.NoSpread or WeaponSettings.NoKick then\n\t\t\tBS_recoilApplied = false\n\t\t\tApplyWeaponHooks()\n\t\tend\n\tend)\n\n\ttask.spawn(function()\n\t\twhile task.wait(1) do\n\t\t\tif (WeaponSettings.NoRecoil or WeaponSettings.NoSpread or WeaponSettings.NoKick) and not BS_recoilApplied then\n\t\t\t\tApplyWeaponHooks()\n\t\t\tend\n\t\tend\n\tend)\n\n\tlocal hitmarkerSize = 9\n\tlocal hitmarkerLines = {}\n\tfor i=1,4 do\n\t\tlocal ln = Drawing.new("Line")\n\t\tln.Thickness = 1.5; ln.Color = Color3.fromRGB(255,255,255)\n\t\tln.Transparency = 1; ln.Visible = false; ln.ZIndex = 1000\n\t\thitmarkerLines[i] = ln\n\tend\n\tlocal activeHitmarkers = {}\n\tfunction ShowHitmarker(worldPos, color, isKill)\n\t\ttable.insert(activeHitmarkers, {pos=worldPos, time=tick(), color=color or Color3.fromRGB(255,255,255),\n\t\t\tsize=isKill and (hitmarkerSize*1.6) or hitmarkerSize, duration=isKill and 0.6 or 0.35})\n\tend\n\tRunService.RenderStepped:Connect(function()\n\t\tif #activeHitmarkers == 0 then return end\n\t\tlocal now = tick()\n\t\tfor i = #activeHitmarkers, 1, -1 do\n\t\t\tlocal hm = activeHitmarkers[i]\n\t\t\tlocal age = now - hm.time\n\t\t\tif age > hm.duration then\n\t\t\t\tfor _, l in ipairs(hitmarkerLines) do l.Visible = false end\n\t\t\t\ttable.remove(activeHitmarkers, i)\n\t\t\telse\n\t\t\t\tlocal sp, on = Camera:WorldToViewportPoint(hm.pos)\n\t\t\t\tif on then\n\t\t\t\t\tlocal sz = hm.size\n\t\t\t\t\tlocal alpha = 1 - (age / hm.duration)\n\t\t\t\t\thitmarkerLines[1].From = Vector2.new(sp.X-sz, sp.Y-sz); hitmarkerLines[1].To = Vector2.new(sp.X-sz/2, sp.Y-sz/2)\n\t\t\t\t\thitmarkerLines[2].From = Vector2.new(sp.X+sz, sp.Y-sz); hitmarkerLines[2].To = Vector2.new(sp.X+sz/2, sp.Y-sz/2)\n\t\t\t\t\thitmarkerLines[3].From = Vector2.new(sp.X-sz, sp.Y+sz); hitmarkerLines[3].To = Vector2.new(sp.X-sz/2, sp.Y+sz/2)\n\t\t\t\t\thitmarkerLines[4].From = Vector2.new(sp.X+sz, sp.Y+sz); hitmarkerLines[4].To = Vector2.new(sp.X+sz/2, sp.Y+sz/2)\n\t\t\t\t\tfor _, l in ipairs(hitmarkerLines) do l.Color = hm.color; l.Transparency = alpha; l.Visible = true end\n\t\t\t\telse\n\t\t\t\t\tfor _, l in ipairs(hitmarkerLines) do l.Visible = false end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\n\n\tlocal hitLogHolder = create("ScreenGui", {Name="HitLog", Parent=LocalPlayer:WaitForChild("PlayerGui"),\n\t\tResetOnSpawn=false, ZIndexBehavior=Enum.ZIndexBehavior.Sibling})\n\tlocal hitLogContainer = create("Frame", {Parent=hitLogHolder, BackgroundTransparency=1,\n\t\tPosition=UDim2.new(1, -260, 1, -250), Size=UDim2.new(0, 250, 0, 240)})\n\tcreate("UIListLayout", {Parent=hitLogContainer, SortOrder=Enum.SortOrder.LayoutOrder,\n\t\tVerticalAlignment=Enum.VerticalAlignment.Bottom, HorizontalAlignment=Enum.HorizontalAlignment.Right, Padding=UDim.new(0, 3)})\n\tfunction AddHitLog(text, color, isKill)\n\t\tlocal frame = create("Frame", {Parent=hitLogContainer, BackgroundColor3=Color3.fromRGB(15,15,15),\n\t\t\tBackgroundTransparency=0.15, BorderSizePixel=0, Size=UDim2.new(1,0,0,24), AutomaticSize=Enum.AutomaticSize.Y})\n\t\tcreate("UICorner", {Parent=frame, CornerRadius=UDim.new(0,3)})\n\t\tcreate("UIStroke", {Parent=frame, Color=color or Color3.fromRGB(255,255,255), Thickness=1, Transparency=0.4})\n\t\tlocal pad = create("UIPadding", {Parent=frame})\n\t\tpad.PaddingLeft = UDim.new(0,8); pad.PaddingRight = UDim.new(0,8); pad.PaddingTop = UDim.new(0,5); pad.PaddingBottom = UDim.new(0,5)\n\t\tcreate("TextLabel", {Parent=frame, BackgroundTransparency=1, Size=UDim2.new(0,16,0,16), Position=UDim2.new(0,0,0,0),\n\t\t\tText=isKill and "X" or ">", TextColor3=color or Color3.fromRGB(255,255,255), Font=Enum.Font.GothamBold,\n\t\t\tTextSize=14, TextXAlignment=Enum.TextXAlignment.Left})\n\t\tcreate("TextLabel", {Parent=frame, BackgroundTransparency=1, Size=UDim2.new(1,-20,0,0), Position=UDim2.new(0,18,0,0),\n\t\t\tAutomaticSize=Enum.AutomaticSize.Y, Text=text, TextColor3=color or Color3.fromRGB(240,240,240),\n\t\t\tFont=Enum.Font.GothamMedium, TextSize=12, TextXAlignment=Enum.TextXAlignment.Left, TextWrapped=true})\n\t\ttask.delay(4, function()\n\t\t\tif frame and frame.Parent then\n\t\t\t\tTweenService:Create(frame, TweenInfo.new(0.4), {BackgroundTransparency=1}):Play()\n\t\t\t\tfor _, c in ipairs(frame:GetDescendants()) do\n\t\t\t\t\tif c:IsA("TextLabel") then TweenService:Create(c, TweenInfo.new(0.4), {TextTransparency=1}):Play() end\n\t\t\t\tend\n\t\t\t\ttask.wait(0.4); frame:Destroy()\n\t\t\tend\n\t\tend)\n\tend\n\n\tlocal wmGui = create("ScreenGui", {Name="MonotonWM", Parent=LocalPlayer:WaitForChild("PlayerGui"),\n\t\tResetOnSpawn=false, ZIndexBehavior=Enum.ZIndexBehavior.Sibling})\n\tlocal wmFrame = create("Frame", {Parent=wmGui, BackgroundColor3=Color3.fromRGB(15,15,15),\n\t\tBackgroundTransparency=0.2, BorderSizePixel=0, Position=UDim2.new(0,15,0,15), Size=UDim2.new(0,220,0,46)})\n\tcreate("UICorner", {Parent=wmFrame, CornerRadius=UDim.new(0,4)})\n\tcreate("UIStroke", {Parent=wmFrame, Color=Color3.fromRGB(91,134,198), Thickness=1, Transparency=0.3})\n\n    \t-- ===== RAINBOW OUTLINE =====\n\tlocal wmStroke = wmFrame:FindFirstChildOfClass("UIStroke")\n\tif wmStroke then\n\t\twmStroke.Thickness = 2\n\t\twmStroke.Transparency = 0\n\t\ttask.spawn(function()\n\t\t\tlocal hue = 0\n\t\t\twhile wmFrame.Parent do\n\t\t\t\thue = (hue + 1) % 360\n\t\t\t\twmStroke.Color = Color3.fromHSV(hue / 360, 1, 1)\n\t\t\t\ttask.wait(0.03)\n\t\t\tend\n\t\tend)\n\tend\n\n\tcreate("TextLabel", {Parent=wmFrame, BackgroundTransparency=1, Size=UDim2.new(1,-10,0,20),\n\t\tPosition=UDim2.new(0,8,0,2), Text="monoton.cc", TextColor3=Color3.fromRGB(91,134,198),\n\t\tFont=Enum.Font.GothamBold, TextSize=14, TextXAlignment=Enum.TextXAlignment.Left})\n\n\tlocal wmInfo = create("TextLabel", {Parent=wmFrame, BackgroundTransparency=1, Size=UDim2.new(1,-10,0,18),\n\t\tPosition=UDim2.new(0,8,0,22), Text="fps: -- | ping: --", TextColor3=Color3.fromRGB(200,200,200),\n\t\tFont=Enum.Font.Code, TextSize=12, TextXAlignment=Enum.TextXAlignment.Left})\n\n\tlocal wmDrag = {on=false, start=Vector2.new(0,0), pos=UDim2.new(0,0,0,0)}\n\twmFrame.InputBegan:Connect(function(inp)\n\t\tif inp.UserInputType==Enum.UserInputType.MouseButton1 then\n\t\t\twmDrag.on=true; wmDrag.start=inp.Position; wmDrag.pos=wmFrame.Position\n\t\tend\n\tend)\n\tUserInputService.InputChanged:Connect(function(inp)\n\t\tif wmDrag.on and inp.UserInputType==Enum.UserInputType.MouseMovement then\n\t\t\tlocal d = inp.Position - wmDrag.start\n\t\t\twmFrame.Position = UDim2.new(wmDrag.pos.X.Scale, wmDrag.pos.X.Offset+d.X, wmDrag.pos.Y.Scale, wmDrag.pos.Y.Offset+d.Y)\n\t\tend\n\tend)\n\tUserInputService.InputEnded:Connect(function(inp)\n\t\tif inp.UserInputType==Enum.UserInputType.MouseButton1 then wmDrag.on=false end\n\tend)\n\n\tlocal fpsFrames, fpsTime = 0, tick()\n\tlocal lastPing = 0\n\tRunService.RenderStepped:Connect(function()\n\t\tfpsFrames = fpsFrames + 1\n\t\tlocal now = tick()\n\t\tif now - fpsTime >= 1 then\n\t\t\tlocal fps = math.floor(fpsFrames / (now - fpsTime))\n\t\t\tfpsFrames = 0\n\t\t\tfpsTime = now\n\n\t\t\tlocal ping = 0\n\t\t\tpcall(function()\n\t\t\t\tping = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue())\n\t\t\tend)\n\t\t\tif ping == 0 then ping = lastPing else lastPing = ping end\n\n\t\t\twmInfo.Text = string.format("fps: %d | ping: %d", fps, ping)\n\t\tend\n\tend)\n\n\tfunction ProcessRaycastResult(result)\n\t\tif AntiaimSettings2.Enabled and AntiaimSettings2.PauseOnShot then\n\t\t\tAA_Paused = tick() + AntiaimSettings2.PauseDuration\n\t\tend\n\t\tif not result or type(result) ~= "table" then return end\n\t\tlocal hits = rawget(result, "Hits")\n\t\tif type(hits) ~= "table" or #hits == 0 then AddHitLog("shut up nigga", Color3.fromRGB(150,150,150)); return end\n\t\tlocal finalHit = hits[#hits]\n\t\tif type(finalHit) ~= "table" then return end\n\t\tlocal hitInstance = finalHit.Instance\n\t\tif not hitInstance then return end\n\t\tlocal hitPos = finalHit.Position or hitInstance.Position\n\t\tlocal model = hitInstance:FindFirstAncestorOfClass("Model")\n\t\tlocal victim = model and Players:GetPlayerFromCharacter(model)\n\t\tif victim then\n\t\t\tlocal hum = victim.Character and victim.Character:FindFirstChildOfClass("Humanoid")\n\t\t\tlocal hp = hum and math.floor(hum.Health) or 0\n\t\t\tlocal isKill = hp <= 0\n\t\t\tAddHitLog("Hit "..victim.Name.." ("..hitInstance.Name..") - "..hp.."hp",\n\t\t\t\tisKill and Color3.fromRGB(255,50,50) or Color3.fromRGB(255,200,100), isKill)\n\t\t\tShowHitmarker(hitPos, isKill and Color3.fromRGB(255,50,50) or Color3.fromRGB(255,255,255), isKill)\n\t\t\tif isKill then\n\t\t\t\tpcall(PlayKillSound)\n\t\t\tend\n\t\tend\n\tend\n\n\tlocal fov_circle = Drawing.new("Circle")\n\tfov_circle.Thickness=1; fov_circle.NumSides=100; fov_circle.Radius=180\n\tfov_circle.Filled=false; fov_circle.Visible=false; fov_circle.ZIndex=999\n\tfov_circle.Transparency=1; fov_circle.Color=Color3.fromRGB(54,57,241)\n\n\tlocal chLines = {}\n\tfor i=1,4 do\n\t\tlocal ln = Drawing.new("Line")\n\t\tln.Thickness = CrosshairSettings.Thickness\n\t\tln.Color = CrosshairSettings.Color\n\t\tln.Visible = false\n\t\tln.ZIndex = 998\n\t\tchLines[i] = ln\n\tend\n\tlocal chGlowLines = {}\n\tfor i=1,4 do\n\t\tlocal ln = Drawing.new("Line")\n\t\tln.Thickness = CrosshairSettings.Thickness + 4\n\t\tln.Color = CrosshairSettings.Color\n\t\tln.Transparency = 0.75\n\t\tln.Visible = false\n\t\tln.ZIndex = 997\n\t\tchGlowLines[i] = ln\n\tend\n\tlocal chGlowLines2 = {}\n\tfor i=1,4 do\n\t\tlocal ln = Drawing.new("Line")\n\t\tln.T