==================================\n\t--  WALLBANG — расширенный поиск Bullet класса\n\t-- ============================================================\n\ttask.spawn(function()\n\t\tif typeof(hookfunction) ~= "function" or typeof(getgc) ~= "function" then\n\t\t\twarn("[Wallbang] hookfunction/getgc недоступны")\n\t\t\treturn\n\t\tend\n\n\t\tlocal bulletClass = nil\n\t\tlocal raycastMethodName = nil\n\n\t\t-- Ищем таблицу с методом *performRaycast* ИЛИ *Raycast* + признаками Bullet\n\t\tfor attempt = 1, 60 do\n\t\t\tfor _, obj in next, getgc(true) do\n\t\t\t\tif type(obj) == "table" then\n\t\t\t\t\t-- Прямой вариант: _performRaycast\n\t\t\t\t\tif typeof(rawget(obj, "_performRaycast")) == "function" then\n\t\t\t\t\t\tbulletClass = obj\n\t\t\t\t\t\traycastMethodName = "_performRaycast"\n\t\t\t\t\t\tbreak\n\t\t\t\t\tend\n\t\t\t\t\t-- Альтернативы\n\t\t\t\t\tfor _, key in ipairs({"performRaycast", "performCast", "_performCast"}) do\n\t\t\t\t\t\tif typeof(rawget(obj, key)) == "function"\n\t\t\t\t\t\t\tand (rawget(obj, "getTrueSpread") ~= nil\n\t\t\t\t\t\t\t\tor rawget(obj, "Spread") ~= nil\n\t\t\t\t\t\t\t\tor rawget(obj, "Bullets") ~= nil) then\n\t\t\t\t\t\t\tbulletClass = obj\n\t\t\t\t\t\t\traycastMethodName = key\n\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\t\tif bulletClass then break end\n\t\t\t\tend\n\t\t\tend\n\t\t\tif bulletClass then break end\n\t\t\ttask.wait(0.5)\n\t\tend\n\n\t\tif not bulletClass then\n\t\t\twarn("[Wallbang] Bullet class не найден")\n\t\t\treturn\n\t\tend\n\n\t\tprint("[Wallbang] Bullet class найден, метод:", raycastMethodName)\n\n\t\tlocal originalMethod = bulletClass[raycastMethodName]\n\t\tlocal oldRaycast\n\t\toldRaycast = hookfunction(originalMethod, function(...)\n\t\t\tlocal returns = table.pack(oldRaycast(...))\n\t\t\tlocal result = returns[1]\n\n\t\t\tif not WallbangSettings.Enabled or type(result) ~= "table" then\n\t\t\t\treturn table.unpack(returns, 1, returns.n)\n\t\t\tend\n\n\t\t\tlocal target = GetWallbangTarget()\n