"},{"LeftUpperLeg","LeftLowerLeg"},{"LeftLowerLeg","LeftFoot"},\n\t\t{"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"},{"RightLowerLeg","RightFoot"}}\n\tlocal BONE_MAP_R6 = {{"Head","Torso"},{"Torso","Left Arm"},{"Torso","Right Arm"},\n\t\t{"Torso","Left Leg"},{"Torso","Right Leg"}}\n\tlocal espInstances = {}\n\tfunction createESP(player)\n\t\tif espInstances[player] then return end\n\t\tlocal o = {BoxOutline=Drawing.new("Square"), Box=Drawing.new("Square"),\n\t\t\tName=Drawing.new("Text"), Distance=Drawing.new("Text"),\n\t\t\tHealthOutline=Drawing.new("Square"), Health=Drawing.new("Square"), Bones={}}\n\t\to.BoxOutline.Thickness=2; o.BoxOutline.Filled=false; o.BoxOutline.Transparency=0.5; o.BoxOutline.Color = ESP.OutlineColor\n\t\to.Box.Thickness=1; o.Box.Filled=false; o.Box.Transparency=1\n\t\to.Name.Center=true; o.Name.Outline=true; o.Name.Font=1; o.Name.Size=13; o.Name.Color=ESP.NameColor\n\t\to.Distance.Center=true; o.Distance.Outline=true; o.Distance.Font=1; o.Distance.Size=12; o.Distance.Color=ESP.DistanceColor\n\t\to.HealthOutline.Thickness=1; o.HealthOutline.Filled=true; o.HealthOutline.Transparency=0.5; o.HealthOutline.Color = ESP.OutlineColor\n\t\to.Health.Filled=true; o.Health.Transparency=1\n\t\tfor i=1,15 do\n\t\t\tlocal ln = Drawing.new("Line"); ln.Thickness=1; ln.Transparency=1; ln.Visible=false\n\t\t\ttable.insert(o.Bones, ln)\n\t\tend\n\t\tespInstances[player] = o\n\tend\n\tfunction removeESP(player)\n\t\tlocal o = espInstances[player]\n\t\tif o then\n\t\t\tfor k, v in pairs(o) do\n\t\t\t\tif type(v)=="table" then for _, b in ipairs(v) do pcall(function() b:Remove() end) end\n\t\t\t\telse pcall(function() v:Remove() end) end\n\t\t\tend\n\t\t\tespInstances[player] = nil\n\t\tend\n\tend\n\tlocal espLastUpdate = 0\n\tRunService.RenderStepped:Connect(function()\n\t\tif not ESP.Enabled then\n\t\t\tfor _, o in pairs(espInstances) do\n\t\t\t\tfor k, v in pairs(o) do\n\t\t\t\t\tif type(v)=="table" then for _, b in ipairs(v) do b.Visible=false end else v.Visible=false end\n\t\t\t\tend\n\t\t\tend\n\t\t\treturn\n\t\tend\n\t\tif tick() - espLastUpdate < 0.03 then return end\n\t\tespLastUpdate = tick()\n\t\tlocal camPos = Camera.CFrame.Position\n\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\tlocal o = espInstances[player]\n\t\t\tif player == LocalPlayer then\n\t\t\t\tif o then removeESP(player) end\n\t\t\t\tcontinue\n\t\t\tend\n\t\t\tlocal char = player.Character\n\t\t\tlocal hum = char and char:FindFirstChildOfClass("Humanoid")\n\t\t\tlocal root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char.PrimaryPart)\n\t\t\tlocal isDead = char and (char:GetAttribute("Dead")==true or (hum and hum.Health<=0))\n\t\t\tlocal allowed = char and root and not isDead\n\t\t\tif allowed and ESP.TeamCheck and getPlayerTeam(player) == "Ally" then allowed = false end\n\t\t\tif allowed and (camPos - root.Position).Magnitude > ESP.MaxDistance then allowed = false end\n\t\t\tif not allowed then\n\t\t\t\tif o then\n\t\t\t\t\tfor k, v in pairs(o) do\n\t\t\t\t\t\tif type(v)=="table" then for _, b in ipairs(v) do b.Visible=false end else v.Visible=false end\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tcontinue\n\t\t\tend\n\t\t\tif not o then createESP(player); o = espInstances[player] end\n\t\t\tlocal targetColor = ESP.BoxColor\n\t\t\tlocal rootPos, onScreen = Camera:WorldToViewportPoint(root.Position)\n\t\t\tif onScreen then\n\t\t\t\tlocal head = char:FindFirstChild("Head")\n\t\t\t\tlocal headPos = head and Camera:WorldToViewportPoint(head.Position) or Camera:WorldToViewportPoint(root.Position + Vector3.new(0,2,0))\n\t\t\t\tlocal legPos = Camera:WorldToViewportPoint(root.Position - Vector3.new(0,3,0))\n\t\t\t\tlocal height = math.abs(headPos.Y - legPos.Y)\n\t\t\t\tlocal width = height / 1.6\n\t\t\t\tlocal boxX = rootPos.X - (width/2)\n\t\t\t\tlocal boxY = headPos.Y\n\t\t\t\to.Box.Visible = ESP.Boxes; o.BoxOutline.Visible = ESP.Boxes\n\t\t\t\tif ESP.Boxes then\n\t\t\t\t\tlocal size = Vector2.new(width, height)\n\t\t\t\t\tlocal pos = Vector2.new(boxX, boxY)\n\t\t\t\t\to.Box.Size = size; o.Box.Position = pos; o.Box.Color = targetColor\n\t\t\t\t\to.BoxOutline.Size = size; o.BoxOutline.Position = pos\n\t\t\t\tend\n\t\t\t\tlocal isR15 = char:FindFirstChild("UpperTorso") ~= nil\n\t\t\t\tlocal activeBoneMap = isR15 and BONE_MAP_R15 or BONE_MAP_R6\n\t\t\t\tfor i, boneLine in ipairs(o.Bones) do\n\t\t\t\t\tlocal conn = activeBoneMap[i]\n\t\t\t\t\tif ESP.Skeletons and conn then\n\t\t\t\t\t\tlocal partA = char:FindFirstChild(conn[1]); local partB = char:FindFirstChild(conn[2])\n\t\t\t\t\t\tif partA and partB then\n\t\t\t\t\t\t\tlocal posA, visA = Camera:WorldToViewportPoint(partA.Position)\n\t\t\t\t\t\t\tlocal posB, visB = Camera:WorldToViewportPoint(partB.Position)\n\t\t\t\t\t\t\tif visA and visB then\n\t\t\t\t\t\t\t\tboneLine.From = Vector2.new(posA.X, posA.Y); boneLine.To = Vector2.new(posB.X, posB.Y)\n\t\t\t\t\t\t\t\tboneLine.Color = targetColor; boneLine.Visible = true\n\t\t\t\t\t\t\telse boneLine.Visible = false end\n\t\t\t\t\t\telse boneLine.Visible = false end\n\t\t\t\t\telse boneLine.Visible = false end\n\t\t\t\tend\n\t\t\t\tif ESP.Names then\n\t\t\t\t\to.Name.Text = player.Name\n\t\t\t\t\to.Name.Position = Vector2.new(rootPos.X, boxY - 15); o.Name.Visible = true\n\t\t\t\telse o.Name.Visible = false end\n\t\t\t\tif ESP.Distance then\n\t\t\t\t\tlocal distance = math.floor((camPos - root.Position).Magnitude)\n\t\t\t\t\to.Distance.Text = tostring(distance).."m"\n\t\t\t\t\to.Distance.Position = Vector2.new(rootPos.X, boxY + height + 2); o.Distance.Visible = true\n\t\t\t\telse o.Distance.Visible = false end\n\t\t\t\tif ESP.Health and hum then\n\t\t\t\t\tlocal barPadding, barWidth = 4, 2\n\t\t\t\t\tlocal barX = boxX - barPadding - barWidth\n\t\t\t\t\tlocal hpPct = math.clamp(hum.Health/hum.MaxHealth, 0, 1)\n\t\t\t\t\tlocal healthHeight = height * hpPct\n\t\t\t\t\to.Health.Color = Color3.fromHex("#32CD32"):Lerp(Color3.fromHex("#FF0000"), 1-hpPct)\n\t\t\t\t\to.HealthOutline.Position = Vector2.new(barX-1, boxY-1)\n\t\t\t\t\to.HealthOutline.Size = Vector2.new(barWidth+2, height+2)\n\t\t\t\t\to.Health.Position = Vector2.new(barX, boxY+(height-healthHeight))\n\t\t\t\t\to.Health.Size = Vector2.new(barWidth, healthHeight)\n\t\t\t\t\to.Health.Visible = true; o.HealthOutline.Visible = true\n\t\t\t\telse o.Health.Visible = false; o.HealthOutline.Visible = false end\n\t\t\telse\n\t\t\t\tfor k, v in pairs(o) do\n\t\t\t\t\tif type(v)=="table" then for _, b in ipairs(v) do b.Visible=false end else v.Visible=false end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\n\tPlayers.PlayerRemoving:Connect(removeESP)\n\n\tlocal VMPos = {Enabled = false, OffsetX = 0, OffsetY = 0, OffsetZ = 0, Pitch = 0, Yaw = 0, Roll = 0}\n\tlocal VMChams = {\n\t\tEnabled = false,\n\t\tMaterial = "ForceField",\n\t\tColor = Color3.fromRGB(0, 255, 255),\n\t\tTransparency = 0.3,\n\t\tReflectance = 0,\n\t\t-- Что красить:\n\t\tIncludeViewmodel = true,\n\t\tIncludeCharacter = false,\n\t\tIncludeAccessories = false,\n\t\tIncludeWorldWeapon = false,\n\t}\n\tlocal vmOriginalMaterial = {}\n\tlocal currentVM = nil\n\tlocal vmPartsLookup = {}\n\tfunction findViewmodel()\n\t\tlocal cam = Workspace.CurrentCamera\n\t\tif not cam then return nil end\n\t\tfor _, c in ipairs(cam:GetChildren()) do\n\t\t\tif c:IsA("Model") then\n\t\t\t\tif c:FindFirstChild("WeaponModel") or c:FindFirstChild("HumanoidRootPart") then return c end\n\t\t\tend\n\t\tend\n\t\tfor _, c in ipairs(cam:GetChildren()) do\n\t\t\tif c:IsA("Model") then\n\t\t\t\tfor _, p in ipairs(c:GetDescendants()) do if p:IsA("MeshPart") then return c end end\n\t\t\tend\n\t\tend\n\t\treturn nil\n\tend\n\tfunction refreshVM()\n\t\tlocal found = findViewmodel()\n\t\tif found ~= currentVM then\n\t\t\tcurrentVM = found; vmOriginalMaterial = {}; vmPartsLookup = {}\n\t\t\tif currentVM then\n\t\t\t\tfor _, p in ipairs(currentVM:GetDescendants()) do\n\t\t\t\t\tif p:IsA("BasePart") or p:IsA("MeshPart") then vmPartsLookup[p] = true end\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\treturn currentVM\n\tend\n\tfunction getAllVMParts()\n\t\tlocal vm = currentVM\n\t\tif not vm or not vm.Parent then return {} end\n\t\tlocal parts = {}\n\t\tfor _, p in ipairs(vm:GetDescendants()) do\n\t\t\tif p:IsA("BasePart") or p:IsA("MeshPart") then table.insert(parts, p) end\n\t\tend\n\t\treturn parts\n\tend\n\tfunction isSkippablePart(part)\n\t\tlocal n = string.lower(part.Name)\n\t\tif n:find("light") or n:find("camera") or n:find("muzzle") or n:find("flash") then return true end\n\t\tfor _, c in ipairs(part:GetChildren()) do\n\t\t\tif c:IsA("Light") then return true end\n\t\t\tif c:IsA("ParticleEmitter") or c:IsA("Smoke") or c:IsA("Fire") then return true end\n\t\tend\n\t\treturn false\n\tend\n\t\tlocal charOriginals = {}\n\tlocal accessoryOriginals = {}\n\tlocal worldWpnOriginals = {}\n\n\tfunction saveOriginal(tbl, part)\n\t\tif not tbl[part] then\n\t\t\ttbl[part] = {\n\t\t\t\tMaterial = part.Material,\n\t\t\t\tColor = part.Color,\n\t\t\t\tTransparency = part.Transparency,\n\t\t\t\tReflectance = part.Reflectance,\n\t\t\t}\n\t\tend\n\tend\n\n\tfunction applyCham(part)\n\t\tpart.Material = Enum.Material[VMChams.Material] or Enum.Material.ForceField\n\t\tpart.Color = VMChams.Color\n\t\tpart.Transparency = VMChams.Transparency\n\t\tpart.Reflectance = VMChams.Reflectance\n\tend\n\n\tfunction restoreCham(tbl, part)\n\t\tlocal o = tbl[part]\n\t\tif o and part and part.Parent then\n\t\t\tpart.Material = o.Material\n\t\t\tpart.Color = o.Color\n\t\t\tpart.Transparency = o.Transparency\n\t\t\tpart.Reflectance = o.Reflectance\n\t\tend\n\t\ttbl[part] = nil\n\tend\n\n\tfunction applyVMMaterial()\n\t\tlocal mat = Enum.Material[VMChams.Material] or Enum.Material.ForceField\n\n\t\t-- === Viewmodel ===\n\t\tif VMChams.Enabled and VMChams.IncludeViewmodel then\n\t\t\tfor _, part in ipairs(getAllVMParts()) do\n\t\t\t\tif isSkippablePart(part) then\n\t\t\t\t\trestoreCham(vmOriginalMaterial, part)\n\t\t\t\telse\n\t\t\t\t\tsaveOriginal(vmOriginalMaterial, part)\n\t\t\t\t\tpart.Material = mat\n\t\t\t\t\tpart.Color = VMChams.Color\n\t\t\t\t\tpart.Transparency = VMChams.Transparency\n\t\t\t\t\tpart.Reflectance = VMChams.Reflectance\n\t\t\t\tend\n\t\t\tend\n\t\telse\n\t\t\tfor part in pairs(vmOriginalMaterial) do\n\t\t\t\trestoreCham(vmOriginalMaterial, part)\n\t\t\tend\n\t\tend\n\n\t\t-- === Character (body parts) ===\n\t\tlocal char = LocalPlayer.Character\n\t\tif VMChams.Enabled and VMChams.IncludeCharacter and char then\n\t\t\tfor _, part in ipairs(char:GetDescendants()) do\n\t\t\t\tif part:IsA("BasePart") then\n\t\t\t\t\tsaveOriginal(charOriginals, part)\n\t\t\t\t\tapplyCham(part)\n\t\t\t\tend\n\t\t\tend\n\t\telse\n\t\t\tfor part in pairs(charOriginals) do\n\t\t\t\trestoreCham(charOriginals, part)\n\t\t\tend\n\t\tend\n\n\t\t-- === Accessories (hats, glasses, etc) ===\n\t\tif VMChams.Enabled and VMChams.IncludeAccessories and char then\n\t\t\tfor _, acc in ipairs(char:GetDescendants()) do\n\t\t\t\tif acc:IsA("Accessory") then\n\t\t\t\t\tlocal handle = acc:FindFirstChild("Handle")\n\t\t\t\t\tif handle and handle:IsA("BasePart") then\n\t\t\t\t\t\tsaveOriginal(accessoryOriginals, handle)\n\t\t\t\t\t\tapplyCham(handle)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\telse\n\t\t\tfor part in pairs(accessoryOriginals) do\n\t\t\t\trestoreCham(accessoryOriginals, part)\n\t\t\tend\n\t\tend\n\n\t\t-- === World weapon (Tool in character, не вьюмодель) ===\n\t\tif VMChams.Enabled and VMChams.IncludeWorldWeapon and char then\n\t\t\tlocal tool = char:FindFirstChildOfClass("Tool")\n\t\t\tif tool then\n\t\t\t\tfor _, part in ipairs(tool:GetDescendants()) do\n\t\t\t\t\tif part:IsA("BasePart") and not isSkippablePart(part) then\n\t\t\t\t\t\tsaveOriginal(worldWpnOriginals, part)\n\t\t\t\t\t\tapplyCham(part)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\telse\n\t\t\tfor part in pairs(worldWpnOriginals) do\n\t\t\t\trestoreCham(worldWpnOriginals, part)\n\t\t\tend\n\t\tend\n\tend\n\n\t-- При респавне очищаем кэши\n\tLocalPlayer.CharacterAdded:Connect(function()\n\t\tcharOriginals = {}\n\t\taccessoryOriginals = {}\n\t\tworldWpnOriginals = {}\n\tend)\n\tlocal vmOldNewIndex\n\tvmOldNewIndex = hookmetamethod(game, "__newindex", newcclosure(function(self, key, value)\n\t\tif not checkcaller() and key == "CFrame" and VMPos.Enabled and vmPartsLookup[self] then\n\t\t\tlocal offset = CFrame.new(VMPos.OffsetX, VMPos.OffsetY, VMPos.OffsetZ)\n\t\t\t\t* CFrame.Angles(math.rad(VMPos.Pitch), math.rad(VMPos.Yaw), math.rad(VMPos.Roll))\n\t\t\tvalue = value * offset\n\t\tend\n\t\treturn vmOldNewIndex(self, key, value)\n\tend))\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(0.2)\n\t\t\trefreshVM()\n\t\t\tif VMChams.Enabled then applyVMMaterial() end\n\t\tend\n\tend)\n\tRunService.RenderStepped:Connect(function()\n\t\tif not currentVM or not currentVM.Parent then refreshVM() end\n\tend)\n\tLocalPlayer.CharacterAdded:Connect(function()\n\t\ttask.wait(0.5)\n\t\tcurrentVM = nil; vmOriginalMaterial = {}; vmPartsLookup = {}\n\t\trefreshVM()\n\tend)\n\n\t-- Menu\n\tlocal window = ui:Window({title="monoton.cc", size=Vector2.new(700, 850)})\n\tlocal generalTab = window:Tab("General")\n\tlocal leftGeneral = generalTab:Section("Main", "left")\n\tlocal rightGeneral = generalTab:Section("Visuals", "right")\n\nlocal cubeTgl = rightGeneral:Toggle({title="Cube Checker", default=false, callback=function(s) CubeCheckerSettings.Enabled=s end})\ncubeTgl:ColorPicker({title="Cube Color", default=Color3.fromRGB(255,0,0), callback=function(c) CubeCheckerSettings.Color=c end})\nrightGeneral:Toggle({title="Cube Rainbow", default=false, callback=function(s) CubeCheckerSettings.Rainbow=s end})\nrightGeneral:Slider({title="Cube Size", min=0.5, max=4, default=1.5, precise=true, callback=function(v) CubeCheckerSettings.Size=v end})\nrightGeneral:Slider({title="Cube Max Dist", min=1, max=5000, default=20, callback=function(v) CubeCheckerSettings.MaxDist=v end})\n\nrightGeneral:Toggle({title="Wallbang Check", default=false, callback