nfAmmo = s\n\t\tif s then BS_startInfAmmo() else BS_stopInfAmmo() end\n\tend})\n\tbsInfAmmo:Keybind({title="Key", default=Enum.KeyCode.F2, bindType="Toggle", callback=function()\n\t\tlocal ns = not WeaponSettings.InfAmmo\n\t\tWeaponSettings.InfAmmo = ns; bsInfAmmo:Set(ns)\n\t\tif ns then BS_startInfAmmo() else BS_stopInfAmmo() end\n\tend})\n\tbsRight:Slider({title="Delay", min=0, max=2, default=0, precise=true, callback=function(v)\n\t\tWeaponSettings.RefillDelay = v\n\t\tif WeaponSettings.InfAmmo then\n\t\t\tBS_stopInfAmmo()\n\t\t\ttask.wait(0.05)\n\t\t\tBS_startInfAmmo()\n\t\tend\n\tend})\nbsRight:Toggle({title="Instant Reload", default=false, callback=function(s) InstantReloadSettings.Enabled=s end})\n\nbsRight:Button({title="All On", callback=function()\n    WeaponSettings.NoRecoil = true\n    WeaponSettings.NoSpread = true\n    WeaponSettings.NoKick   = true\n    WeaponSettings.InfAmmo  = true\n    bsNoRecoil:Set(true)\n    bsInfAmmo:Set(true)\n    if not BS_recoilApplied then BS_applyNoRecoil() end\n    BS_startInfAmmo()\nend})\n\n    \t-- ============================================================\n\t--  FIRERATE\n\t-- ============================================================\n\tlocal FirerateSettings = { Enabled = false, Value = 0.01 }\n\tlocal firerateObjects = {}\n\tlocal firerateOriginal = {}\n\n\ttask.spawn(function()\n\t\ttask.wait(2)\n\t\tpcall(function()\n\t\t\tfor _, obj in next, getgc(true) do\n\t\t\t\tif type(obj) == "table" and rawget(obj, "FireRate") then\n\t\t\t\t\tpcall(function()\n\t\t\t\t\t\ttable.insert(firerateObjects, obj)\n\t\t\t\t\t\ttable.insert(firerateOriginal, table.clone(obj))\n\t\t\t\t\tend)\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\t\tprint("[Firerate] Collected", #firerateObjects, "objects")\n\tend)\n\n\ttask.spawn(function()\n\t\twhile task.wait(0.1) do\n\t\t\tpcall(function()\n\t\t\t\tif FirerateSettings.Enabled then\n\t\t\t\t\tfor _, obj in next, firerateObjects do\n\t\t\t\t\t\tpcall(function()\n\t\t\t\t\t\t\tsetreadonly(obj, false)\n\t\t\t\t\t\t\trawset(obj, "FireRate", math.max(FirerateSettings.Value, 0.01))\n\t\t\t\t\t\t\tsetreadonly(obj, true)\n\t\t\t\t\t\tend)\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\tfor i, obj in next, firerateObjects do\n\t\t\t\t\t\tpcall(function()\n\t\t\t\t\t\t\tif firerateOriginal[i] then\n\t\t\t\t\t\t\t\tsetreadonly(obj, false)\n\t\t\t\t\t\t\t\trawset(obj, "FireRate", firerateOriginal[i].FireRate)\n\t\t\t\t\t\t\t\tsetreadonly(obj, true)\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend)\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\tend)\n\n\tlocal fireTgl = bsRight:Toggle({title="Firerate Changer", default=false, callback=function(s)\n\t\tFirerateSettings.Enabled = s\n\tend})\n\tfireTgl:Keybind({title="Key", default=Enum.KeyCode.F7, bindType="Toggle", callback=function()\n\t\tlocal ns = not FirerateSettings.Enabled\n\t\tFirerateSettings.Enabled = ns\n\t\tfireTgl:Set(ns)\n\tend})\n\tbsRight:Slider({title="Firerate", min=0.00001, max=0.01, default=0.01, precise=true,\n\t\tcallback=function(v) FirerateSettings.Value = v end})\n\n\tlocal configTab = window:Tab("Config")\n\tlocal leftCfg = configTab:Section("Save", "left")\n\tlocal rightCfg = configTab:Section("Manage", "right")\n\tlocal cfgName = ""\n\tleftCfg:Input({title="Name", default="default", callback=function(v) cfgName = v end})\n\tlocal cfgListDropdown = leftCfg:Dropdown({\n\t\ttitle = "Configs",\n\t\toptions = (function()\n\t\t\tlocal l = ConfigSystem:List()\n\t\t\tif #l == 0 then l = {"(empty)"} end\n\t\t\treturn l\n\t\tend)(),\n\t\tdefault = "(empty)",\n\t\tcallback = function(opt)\n\t\t\tif opt and opt ~= "(empty)" then cfgName = opt end\n\t\tend\n\t})\n\tleftCfg:Button({title="Save", callback=function()\n\t\tif cfgName and cfgName ~= "" then ConfigSystem:Save(cfgName) end\n\tend})\n\tleftCfg:Button({title="Load", callback=function()\n\t\tif cfgName and cfgName ~= "" then ConfigSystem:Load(cfgName) end\n\tend})\n\trightCfg:Button({title="Refresh", callback=function()\n\t\tlocal l = ConfigSystem:List()\n\t\tif #l == 0 then l = {"(empty)"} end\n\t\tcfgListDropdown.options = l\n\tend})\n\trightCfg:Button({title="Delete", callback=function()\n\t\tif cfgName and cfgName ~= "" then ConfigSystem:Delete(cfgName) end\n\tend})\n\n\tlocal themeTab = window:Tab("Theme")\n\tlocal leftTheme = themeTab:Section("Colors", "left")\n\tlocal rightTheme = themeTab:Section("Plastic", "right")\n\tfunction addThemeColor(section, label, key)\n\t\tlocal tgl = section:Toggle({title=label, default=true, callback=function() end})\n\t\ttgl:ColorPicker({title=label, default=UITheme[key], callback=function(c) UITheme:SetColor(key, c) end})\n\tend\n\taddThemeColor(leftTheme, "BG", "BG")\n\taddThemeColor(leftTheme, "Panel", "Panel")\n\taddThemeColor(leftTheme, "Section", "Section")\n\taddThemeColor(leftTheme, "Element", "Element")\n\taddThemeColor(leftTheme, "Accent", "Accent")\n\taddThemeColor(leftTheme, "Text", "Text")\n\taddThemeColor(leftTheme, "Stroke", "Stroke")\n\trightTheme:Toggle({title="Corners", default=true, callback=function(s) UITheme.Plastic=s; UITheme:Apply() end})\n\trightTheme:Toggle({title="Blur", default=false, callback=function(s)\n\t\tlocal b = Lighting:FindFirstChild("ThemeBlur")\n\t\tif s and not b then\n\t\t\tb = Instance.new("BlurEffect"); b.Name="ThemeBlur"; b.Parent=Lighting; b.Size=8\n\t\t\tb:SetAttribute("FPSKeep", true)\n\t\telseif not s and b then b:Destroy() end\n\tend})\n\trightTheme:Slider({title="Transp", min=0, max=0.9, default=0, precise=0.05, callback=function(v) UITheme.Transparency=v; UITheme:Apply() end})\n\ttask.delay(0.1, function()\n\t\tlocal gui = LocalPlayer.PlayerGui:FindFirstChild("Ui")\n\t\tif gui then UITheme:Register(gui); UITheme:Apply() end\n\tend)\n\n\tlocal fpsTab = window:Tab("Perf")\n\tlocal leftFPS = fpsTab:Section("FPS", "left")\n\tlocal rightFPS = fpsTab:Section("Opts", "right")\n\tleftFPS:Toggle({title="FPS Boost", default=false, callback=function(s) FPSBoost:Toggle(s) end})\n\tleftFPS:Toggle({title="No Fog", default=true, callback=function(s) FPSBoost.RemoveFog=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\tleftFPS:Toggle({title="No Shadows", default=true, callback=function(s) FPSBoost.RemoveShadows=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\tleftFPS:Toggle({title="No PostFX", default=true, callback=function(s) FPSBoost.RemovePostFX=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\trightFPS:Toggle({title="No Particles", default=true, callback=function(s) FPSBoost.RemoveParticles=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\trightFPS:Toggle({title="No Textures", default=false, callback=function(s) FPSBoost.RemoveTextures=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\trightFPS:Toggle({title="Hide Sky", default=false, callback=function(s) FPSBoost.HideSky=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\trightFPS:Toggle({title="Low Quality", default=true, callback=function(s) FPSBoost.LowerQuality=s; if FPSBoost.Enabled then FPSBoost:Apply() end end})\n\n\tlocal OverlaySettings = { WaifuEnabled = true, RainEnabled = true }\n\n\tlocal waifuGui = Instance.new("ScreenGui")\n\twaifuGui.Name = "WaifuOverlay"\n\twaifuGui.ResetOnSpawn = false\n\twaifuGui.IgnoreGuiInset = true\n\twaifuGui.DisplayOrder = 100\n\tpcall(function() waifuGui.Parent = game:GetService("CoreGui") end)\n\tif not waifuGui.Parent then waifuGui.Parent = LocalPlayer:WaitForChild("PlayerGui") end\n\n\tlocal waifuImage = Instance.new("ImageLabel")\n\twaifuImage.Name = "Waifu"\n\twaifuImage.Size = UDim2.new(0, 260, 0, 300)\n\twaifuImage.Position = UDim2.new(1, -275, 1, -315)\n\twaifuImage.BackgroundTransparency = 1\n\twaifuImage.Image = "rbxassetid://1234567890"\n\twaifuImage.ScaleType = Enum.ScaleType.Fit\n\twaifuImage.Visible = false\n\twaifuImage.ZIndex = 5\n\twaifuImage.Parent = waifuGui\n\n\tlocal rainDrops = {}\n\tlocal RAIN_COUNT = 60\n\tfor i = 1, RAIN_COUNT do\n\t\tlocal ln = Drawing.new("Line")\n\t\tln.Thickness = 1\n\t\tln.Color = Color3.fromRGB(180, 200, 255)\n\t\tln.Transparency = 0.4\n\t\tln.Visible = false\n\t\tln.ZIndex = 5\n\t\ttable.insert(rainDrops, {\n\t\t\tLine = ln,\n\t\t\tX = math.random() * 2000 - 1000,\n\t\t\tY = math.random() * 1080,\n\t\t\tSpeed = math.random(600, 1000),\n\t\t\tLength = math.random(12, 22),\n\t\t\tSlant = 3,\n\t\t})\n\tend\n\n\tRunService.RenderStepped:Connect(function(dt)\n\t\tlocal menuOpen = false\n\t\tlocal gui = LocalPlayer.PlayerGui:FindFirstChild("Ui")\n\t\tif gui then menuOpen = gui.Enabled end\n\t\twaifuImage.Visible = OverlaySettings.WaifuEnabled and menuOpen\n\t\tif not (OverlaySettings.RainEnabled and menuOpen) then\n\t\t\tfor _, d in ipairs(rainDrops) do d.Line.Visible = false end\n\t\t\treturn\n\t\tend\n\t\tlocal viewport = Camera.ViewportSize\n\t\tfor _, d in ipairs(rainDrops) do\n\t\t\td.Y = d.Y + d.Speed * dt\n\t\t\td.X = d.X + d.Slant * dt * 60\n\t\t\tif d.Y > viewport.Y + 20 then\n\t\t\t\td.Y = -20\n\t\t\t\td.X = math.random() * viewport.X\n\t\t\tend\n\t\t\tif d.X > viewport.X then d.X = d.X - viewport.X end\n\t\t\td.Line.From = Vector2.new(d.X, d.Y)\n\t\t\td.Line.To = Vector2.new(d.X + d.Slant, d.Y + d.Length)\n\t\t\td.Line.Color = Color3.fromRGB(180, 200, 255)\n\t\t\td.Line.Thickness = 1\n\t\t\td.Line.Transparency = 0.4\n\t\t\td.Line.Visible = true\n\t\tend\n\tend)\n\n\tlocal overlayTab = window:Tab("Overlay")\n\tlocal lOv = overlayTab:Section("Overlay", "left")\n\tlOv:Toggle({title="Waifu", default=true, callback=function(s) OverlaySettings.WaifuEnabled = s end})\n\tlOv:Toggle({title="Rain", default=true, callback=function(s) OverlaySettings.RainEnabled = s end})\n\tlocal rOv = overlayTab:Section("Image", "right")\n\trOv:Input({title="Asset ID", default="rbxassetid://1234567890", callback=function(v) waifuImage.Image = v end})\n\trOv:Slider({title="Size", min=100, max=500, default=260, callback=function(v)\n\t\twaifuImage.Size = UDim2.new(0, v, 0, v * 1.15)\n\tend})\n\n\tRunService.RenderStepped:Connect(function(dt)\n\t\tif not TargetBoxSettings.Enabled then\n\t\t\tTargetBox.Outline.Visible = false\n\t\t\tTargetBox.Fill.Visible = false\n\t\t\tTargetBox.Glow.Visible = false\n\t\t\treturn\n\t\tend\n\t\tlocal mousePos = UserInputService:GetMouseLocation()\n\t\t\t\tlocal target = nil\n\t\tif SilentAimSettings.Enabled then target = GetSilentTarget() end\n\t\tlocal color = target and TargetBoxSettings.VisibleColor or TargetBoxSettings.NeutralColor\n\t\tTargetBox.SpinAngle = TargetBox.SpinAngle + TargetBoxSettings.Spin * dt\n\t\tif TargetBox.SpinAngle >= 360 then TargetBox.SpinAngle = TargetBox.SpinAngle - 360 end\n\t\tlocal rad = math.rad(TargetBox.SpinAngle)\n\t\tlocal cs, sn = math.cos(rad), math.sin(rad)\n\t\tlocal size = TargetBoxSettings.Size\n\t\tlocal half = size / 2\n\t\tlocal cx, cy = mousePos.X, mousePos.Y\n\t\tif TargetBoxSettings.Spin == 0 then\n\t\t\tTargetBox.Fill.Size = Vector2.new(size, size)\n\t\t\tTargetBox.Fill.Position = Vector2.new(cx - half, cy - half)\n\t\t\tTargetBox.Fill.Color = color\n\t\t\tTargetBox.Fill.Visible = true\n\t\t\tTargetBox.Outline.Size = Vector2.new(size, size)\n\t\t\tTargetBox.Outline.Position = Vector2.new(cx - half, cy - half)\n\t\t\tTargetBox.Outline.Color = color\n\t\t\tTargetBox.Outline.Visible = true\n\t\telse\n\t\t\tif not TargetBox.SpinLines then\n\t\t\t\tTargetBox.SpinLines = {}\n\t\t\t\tfor i = 1, 4 do\n\t\t\t\t\tTargetBox.SpinLines[i] = Drawing.new("Line")\n\t\t\t\t\tTargetBox.SpinLines[i].Thickness = TargetBoxSettings.Thickness\n\t\t\t\t\tTargetBox.SpinLines[i].Transparency = 1\n\t\t\t\tend\n\t\t\tend\n\t\t\tlocal corners = {{-half, -half},{half, -half},{half, half},{-half, half}}\n\t\t\tfor i = 1, 4 do\n\t\t\t\tlocal a = corners[i]\n\t\t\t\tlocal b = corners[(i % 4) + 1]\n\t\t\t\tlocal ax = cx + a[1]*cs - a[2]*sn\n\t\t\t\tlocal ay = cy + a[1]*sn + a[2]*cs\n\t\t\t\tlocal bx = cx + b[1]*cs - b[2]*sn\n\t\t\t\tlocal by = cy + b[1]*sn + b[2]*cs\n\t\t\t\tTargetBox.SpinLines[i].From = Vector2.new(ax, ay)\n\t\t\t\tTargetBox.SpinLines[i].To = Vector2.new(bx, by)\n\t\t\t\tTargetBox.SpinLines[i].Color = color\n\t\t\t\tTargetBox.SpinLines[i].Visible = true\n\t\t\tend\n\t\t\tTargetBox.Fill.Visible = false\n\t\t\tTargetBox.Outline.Visible = false\n\t\tend\n\t\tif TargetBoxSettings.Glow then\n\t\t\tTargetBox.Glow.Size = Vector2.new(size + 8, size + 8)\n\t\t\tTargetBox.Glow.Position = Vector2.new(cx - half - 4, cy - half - 4)\n\t\t\tTargetBox.Glow.Color = color\n\t\t\tTargetBox.Glow.Transparency = 0.8\n\t\t\tTargetBox.Glow.Visible = true\n\t\telse\n\t\t\tTargetBox.Glow.Visible = false\n\t\tend\n\tend)\n\n\tUserInputService.InputBegan:Connect(function(input, gp)\n\t\tif gp then return end\n\t\tif input.KeyCode == Enum.KeyCode.F1 then\n\t\t\tlocal on = not (WeaponSettings.NoRecoil and WeaponSettings.InfAmmo)\n\t\t\tWeaponSettings.NoRecoil = on; WeaponSettings.NoSpread = on\n\t\t\tWeaponSettings.NoKick = on; WeaponSettings.InfAmmo = on\n\t\t\tbsNoRecoil:Set(on); bsInfAmmo:Set(on)\n\t\t\tif on then\n\t\t\t\tif not BS_recoilApplied then BS_applyNoRecoil() end\n\t\t\t\tBS_startInfAmmo()\n\t\t\telse BS_stopInfAmmo() end\n\t\tend\n\t\tif input.KeyCode == Enum.KeyCode.F4 then\n\t\t\tWalkSettings.Enabled = not WalkSettings.Enabled\n\t\tend\n\t\tif input.KeyCode == Enum.KeyCode.F5 then\n\t\t\tAutoJumpSettings.Enabled = not AutoJumpSettings.Enabled\n\t\t\tif AutoJumpSettings.Enabled then startAutoJump() else stopAutoJump() end\n\t\tend\n\t\tif input.KeyCode == Enum.KeyCode.F6 then\n\t\t\tnightTgl:Set(not NightSettings.Enabled)\n\t\tend\n\t\tif input.KeyCode == Enum.KeyCode.RightShift then\n\t\t\tlocal gui = LocalPlayer.PlayerGui:FindFirstChild("Ui")\n\t\t\tif gui then\n\t\t\t\tgui.Enabled = not gui.Enabled\n\t\t\t\tif gui.Enabled then\n\t\t\t\t\tMenuBlur.Size = 0\n\t\t\t\t\tMenuBlur.Enabled = true\n\t\t\t\t\tTweenService:Create(MenuBlur, TweenInfo.new(0.3), {Size = 12}):Play()\n\t\t\t\telse\n\t\t\t\t\tlocal t = TweenService:Create(MenuBlur, TweenInfo.new(0.25), {Size = 0})\n\t\t\t\t\tt:Play()\n\t\t\t\t\tt.Completed:Connect(function()\n\t\t\t\t\t\tMenuBlur.Enabled = false\n\t\t\t\t\t\