function makeDraggable(p3)
  local v16 = false
  local inputBegan = p3.InputBegan
  local position, position2

  inputBegan:Connect(function(p4)
    if p4.UserInputType == Enum.UserInputType.MouseButton1 then
      v16 = true
      position = p4.Position
      position2 = p3.Position
    end
  end)

  userInputService.InputChanged:Connect(function(input)
    if v16 and input.UserInputType == Enum.UserInputType.MouseMovement then
      local v17 = input.Position - position

      p3.Position = UDim2.new(
        position2.X.Scale, position2.X.Offset + v17.X, position2.Y.Scale,
        position2.Y.Offset + v17.Y
      )
    end
  end)

  userInputService.InputEnded:Connect(function(input2)
    if input2.UserInputType == Enum.UserInputType.MouseButton1 then
      v16 = false
    end
  end)
end

function create(p5, p6)
  local instance = Instance.new(p5)

  for key3, value2 in pairs(p6) do
    instance[key3] = value2
  end

  return instance
end

